// ─── German + French lesson section bodies (all 36 lessons) ──────────────────
// Parallel to the es/ru/mk body catalogs; arrays follow section order and are
// merged into BODY_TRANS (contentTranslations.ts). Built in era batches.
type L = 'de' | 'fr';

export const DEFR_BODY: Record<string, Partial<Record<L, string[]>>> = {
  'ancient-01': {
    de: [
      "Um 3500 v. Chr. errichteten die Sumerer im südlichen Mesopotamien — dem Land zwischen Euphrat und Tigris im heutigen Irak — die ersten Städte der Welt. Uruk, die größte, beherbergte womöglich 50.000 Menschen. Um Getreideüberschüsse und Tempelkonten zu verwalten, erfanden sumerische Schreiber um 3100 v. Chr. die Keilschrift, indem sie keilförmige Zeichen in Tontafeln drückten.\n\nDiese Schrift verbreitete sich über den Nahen Osten und blieb mehr als 3.000 Jahre die vorherrschende Schrift. Die mesopotamischen Stadtstaaten entwickelten zudem Bronzewerkzeuge, das Rad und ausgeklügelte Bewässerungskanäle, die Wüste in Ackerland verwandelten.",
      "Ägyptens Zivilisation entstand am Nil etwa zur selben Zeit wie Sumer. Die jährliche Nilflut lagerte fruchtbaren Schlamm ab und machte Ägypten zu einer der fruchtbarsten Regionen der Antike. Um 3100 v. Chr. unter Pharao Narmer geeint, bildete Ägypten einen starken Zentralstaat unter göttlichen Königen.\n\nWährend des Alten Reiches (ca. 2686–2181 v. Chr.) ließen die Pharaonen die großen Pyramiden von Giza errichten — Ingenieurleistungen, die bis heute ehrfurchtgebietend sind. Ägyptische Hieroglyphen, Mathematik und Medizin zählten zu den fortschrittlichsten der Antike.",
      "Der babylonische König Hammurabi (reg. 1792–1750 v. Chr.) einte Mesopotamien und erließ einen der frühesten schriftlichen Gesetzestexte der Welt. Der Kodex Hammurabi legte Strafen für Verbrechen fest und regelte den Handel und spiegelte eine auf Handel und Rechtsordnung gebaute Gesellschaft wider.\n\nSowohl Ägypten als auch Mesopotamien unterhielten weitreichende Handelsnetze. Ägyptisches Gold und Getreide flossen in die Levante; mesopotamische Kaufleute handelten mit dem Indus-Tal. Diese frühen Zivilisationen schufen die Blaupause für organisierte Regierung, Religion, Landwirtschaft und Stadtleben, auf der alle späteren Gesellschaften aufbauen sollten.",
      "Religion war in beiden Zivilisationen untrennbar mit politischer Macht verbunden. Die Sumerer verehrten ein Pantheon von Göttern, die Naturgewalten beherrschten — Stürme, Fluten, Fruchtbarkeit — und errichteten hoch aufragende Zikkurats als Tempel zu ihren Ehren. Priester besaßen enormen Einfluss, verwalteten Tempelländereien und beaufsichtigten riesige Kornspeicher. Die wichtigste Gottheit, Enlil, galt als König der Götter, dessen Gunst über das Schicksal einer Stadt entschied.\n\nDie ägyptische Religion kreiste um das Jenseits und die kosmische Ordnung (Maat). Pharaonen galten als lebende Götter — Verkörperungen des Horus im Leben und des Osiris im Tod. Der aufwendige Prozess der Mumifizierung und der Bau von Pyramidengräbern sollten den Leib des Pharaos für das ewige Leben bewahren. Diese religiösen Systeme gaben den Menschen Sinn, legitimierten politische Autorität und trieben architektonische Leistungen von atemberaubendem Ehrgeiz an.",
      "Unter ihrem religiösen Weltbild machten mesopotamische und ägyptische Gelehrte erstaunliche praktische Fortschritte. Babylonische Mathematiker entwickelten ein Zahlensystem zur Basis 60 — Ursprung unserer 60-Minuten-Stunde und des 360-Grad-Kreises. Sie lösten quadratische Gleichungen und verfolgten über Jahrhunderte mit peinlicher Genauigkeit die Bewegungen der Planeten.\n\nDie ägyptische Medizin war ebenso beeindruckend. Der Papyrus Edwin Smith (ca. 1600 v. Chr.) beschreibt chirurgische Behandlungen mit klinischer Beobachtung und erkennt, dass Hirnverletzungen bestimmte Lähmungen verursachen. Ägyptische Ärzte verstanden die Anatomie durch die Mumifizierung und entwickelten Behandlungen für Knochenbrüche und Infektionen. Dieser Bestand an praktischem Wissen, wenn auch mit magischen Heilmitteln vermengt, legte das Fundament für die spätere griechische Medizin und letztlich für die moderne Wissenschaft.",
    ],
    fr: [
      "Vers 3500 av. J.-C., les Sumériens du sud de la Mésopotamie — la terre entre le Tigre et l'Euphrate dans l'Irak actuel — bâtirent les premières villes du monde. Uruk, la plus grande, comptait peut-être 50 000 habitants. Pour gérer les surplus de grain et les comptes des temples, les scribes sumériens inventèrent l'écriture cunéiforme vers 3100 av. J.-C., imprimant des signes en coin dans des tablettes d'argile.\n\nCette écriture se répandit à travers le Proche-Orient et resta l'écriture dominante pendant plus de 3 000 ans. Les cités-États mésopotamiennes développèrent aussi des outils de bronze, la roue et des canaux d'irrigation sophistiqués qui transformèrent le désert en terres cultivées.",
      "La civilisation égyptienne naquit le long du Nil à peu près en même temps que Sumer. La crue annuelle du Nil déposait un limon fertile, faisant de l'Égypte l'une des régions les plus fécondes du monde antique. Unifiée sous le pharaon Narmer vers 3100 av. J.-C., l'Égypte forma un État centralisé fort dirigé par des rois-dieux.\n\nSous l'Ancien Empire (v. 2686–2181 av. J.-C.), les pharaons firent bâtir les grandes pyramides de Gizeh — prouesses d'ingénierie qui émerveillent encore aujourd'hui. Les hiéroglyphes, les mathématiques et la médecine égyptiens comptaient parmi les plus avancés de l'Antiquité.",
      "Le roi babylonien Hammurabi (r. 1792–1750 av. J.-C.) unifia la Mésopotamie et promulgua l'un des plus anciens codes de lois écrits du monde. Le Code de Hammurabi fixait des peines pour les crimes et réglementait le commerce, reflétant une société fondée sur l'échange et l'ordre juridique.\n\nL'Égypte comme la Mésopotamie entretenaient de vastes réseaux commerciaux. L'or et le grain égyptiens gagnaient le Levant ; les marchands mésopotamiens commerçaient avec la vallée de l'Indus. Ces premières civilisations établirent le modèle du gouvernement organisé, de la religion, de l'agriculture et de la vie urbaine sur lequel toutes les sociétés ultérieures bâtiraient.",
      "La religion était indissociable du pouvoir politique dans les deux civilisations. Les Sumériens vénéraient un panthéon de dieux maîtrisant les forces naturelles — tempêtes, crues, fécondité — et élevaient d'imposantes ziggourats en guise de temples. Les prêtres exerçaient une influence énorme, administrant les terres des temples et surveillant de vastes greniers. La divinité principale, Enlil, était vue comme le roi des dieux dont la faveur décidait du sort d'une cité.\n\nLa religion égyptienne était centrée sur l'au-delà et l'ordre cosmique (Maât). Les pharaons étaient tenus pour des dieux vivants — incarnations d'Horus dans la vie et d'Osiris dans la mort. Le processus élaboré de momification et la construction de tombes pyramidales visaient à préserver le corps du pharaon pour la vie éternelle. Ces systèmes religieux donnaient un sens aux gens, légitimaient l'autorité politique et suscitaient des réalisations architecturales d'une ambition vertigineuse.",
      "Sous leur vision religieuse du monde, les savants mésopotamiens et égyptiens firent d'étonnants progrès pratiques. Les mathématiciens babyloniens élaborèrent un système numérique en base 60 — source de notre heure de 60 minutes et du cercle de 360 degrés. Ils résolvaient des équations quadratiques et suivaient les mouvements planétaires sur des siècles avec une précision méticuleuse.\n\nLa médecine égyptienne était tout aussi remarquable. Le papyrus Edwin Smith (v. 1600 av. J.-C.) décrit des traitements chirurgicaux avec observation clinique, reconnaissant que les lésions cérébrales causent des paralysies précises. Les médecins égyptiens comprenaient l'anatomie par la momification et développèrent des traitements pour les fractures et les infections. Ce corpus de savoir pratique, quoique mêlé de remèdes magiques, posa les bases de la médecine grecque ultérieure et, à terme, de la science moderne.",
    ],
  },
  'ancient-02': {
    de: [
      "Das antike Griechenland war keine geeinte Nation, sondern eine Ansammlung unabhängiger Stadtstaaten (Poleis) mit je eigener Regierung und Kultur. Athen und Sparta waren die mächtigsten. Sparta entwickelte eine militaristische Gesellschaft; jeder männliche Bürger wurde ab dem siebten Lebensjahr zum Soldaten ausgebildet. Athen dagegen wurde zum Zentrum von Kunst, Philosophie und politischer Neuerung.\n\nUm 508 v. Chr. führte der athenische Reformer Kleisthenes die Demokratia ein — die Herrschaft des Volkes, die erste demokratische Regierung der Welt. Bürger (freie erwachsene Männer) stimmten in der Volksversammlung unmittelbar über Gesetze und Politik ab — eine revolutionäre Idee, die alle künftigen Demokratien prägen sollte.",
      "Als das Perserreich 490 v. Chr. in Griechenland einfiel, schlugen die Athener es bei Marathon. Eine zweite persische Invasion 480 v. Chr. erlebte den legendären Stand der Spartaner bei den Thermopylen, ehe die Athener die persische Flotte bei Salamis vernichteten.\n\nDer Sieg über Persien führte Athen auf den Gipfel seiner Macht. Der athenische Staatsmann Perikles nutzte Tributgelder, um auf der Akropolis den Parthenon zu errichten, ein Meisterwerk klassischer Architektur. Doch die Rivalität zwischen Athen und Sparta entlud sich im verheerenden Peloponnesischen Krieg (431–404 v. Chr.), der beide Mächte erschöpfte.",
      "Das klassische Athen brachte einige der größten Denker der Geschichte hervor. Sokrates lehrte durch Fragen und forderte die Athener heraus, ihre Überzeugungen zu prüfen. Seine Methode — die sokratische Methode — steht bis heute im Zentrum der Bildung. Sokrates wurde 399 v. Chr. wegen „Verderbung der Jugend“ zum Tode verurteilt.\n\nSein Schüler Platon verfasste Dialoge über Gerechtigkeit, Schönheit und den idealen Staat. Platons Schüler Aristoteles systematisierte Logik, Biologie, Ethik und Politik — ein Bestand an Methode und Wissen, den europäische Universitäten noch zweitausend Jahre später lehren sollten.",
      "Griechische Kunst und Architektur strebten nach idealer Schönheit und Proportion. Der Parthenon auf der Athener Akropolis — zwischen 447 und 432 v. Chr. unter der Aufsicht des Bildhauers Phidias errichtet — verkörpert dieses Streben. Seine Säulen wölben sich in der Mitte leicht nach außen, um optische Täuschungen auszugleichen und den Eindruck vollkommener Geradheit zu erzeugen. Griechische Bildhauer wie Myron und Praxiteles stellten den menschlichen Körper in idealisierten, naturnahen Posen dar und übertrafen die starre Frontalität früherer Stile bei weitem.\n\nDie 776 v. Chr. in Olympia zu Ehren des Zeus gegründeten Olympischen Spiele versammelten alle vier Jahre Athleten aus der ganzen griechischen Welt. Während der Spiele ruhten die Kriege unter einem heiligen Gottesfrieden. Zu den Wettkämpfen zählten Lauf, Ringen, Diskuswurf, Wagenrennen und der Fünfkampf. Olympiasieger gewannen nur einen Olivenkranz — wurden aber in ihren Heimatstädten als Helden gefeiert und in Siegesoden von Dichtern wie Pindar verewigt. Die Spiele verkörperten das griechische Ideal der Arete: Vortrefflichkeit, Tugend und Wettstreit.",
      "Im späten vierten Jahrhundert v. Chr. trugen makedonische Eroberungen griechische Sprache, Kultur und Einrichtungen über einen weiten Teil der antiken Welt — von Ägypten bis Baktrien (das heutige Afghanistan). Diese „hellenistische“ Welt erhielt prächtige Städte: Alexandria in Ägypten mit seiner legendären Bibliothek von vielleicht 500.000 Schriftrollen; Antiochia in Syrien; Pergamon in Anatolien. Diese kosmopolitischen Zentren verschmolzen griechische, persische, ägyptische und indische Traditionen.\n\nHellenistische Gelehrte machten spektakuläre Fortschritte. Eratosthenes berechnete den Erdumfang mit erstaunlicher Genauigkeit anhand von Schatten und Geometrie. Euklid systematisierte die Geometrie; Archimedes berechnete Pi und entdeckte die Prinzipien von Auftrieb und Hebel. Aristarch schlug gar vor, dass die Erde die Sonne umkreise — siebzehn Jahrhunderte vor Kopernikus. Als Rom schließlich die hellenistischen Königreiche einverleibte, bewahrte und übermittelte es dieses geistige Erbe und machte das klassische Griechenland zum Quell der westlichen Zivilisation.",
    ],
    fr: [
      "La Grèce antique n'était pas une nation unifiée mais un ensemble de cités-États (poleis) indépendantes, chacune avec son gouvernement et sa culture. Athènes et Sparte étaient les plus puissantes. Sparte développa une société militariste ; tout citoyen mâle était formé au métier des armes dès l'âge de sept ans. Athènes, en revanche, devint un centre d'art, de philosophie et d'innovation politique.\n\nVers 508 av. J.-C., le réformateur athénien Clisthène instaura la démokratia — le gouvernement du peuple, la première démocratie du monde. Les citoyens (hommes adultes libres) votaient directement les lois à l'Assemblée, une idée révolutionnaire qui influencerait toutes les démocraties à venir.",
      "Lorsque l'Empire perse envahit la Grèce en 490 av. J.-C., les Athéniens le battirent à Marathon. Une seconde invasion perse en 480 av. J.-C. vit la résistance légendaire des Spartiates aux Thermopyles avant que les Athéniens ne détruisent la flotte perse à Salamine.\n\nLa victoire sur la Perse porta Athènes au faîte de sa puissance. Le dirigeant athénien Périclès employa l'argent du tribut pour bâtir le Parthénon sur l'Acropole, chef-d'œuvre de l'architecture classique. Mais la rivalité entre Athènes et Sparte éclata dans la dévastatrice guerre du Péloponnèse (431–404 av. J.-C.), qui épuisa les deux puissances.",
      "L'Athènes classique produisit quelques-uns des plus grands penseurs de l'histoire. Socrate enseignait par le questionnement, poussant les Athéniens à examiner leurs croyances. Sa méthode — la maïeutique — reste au cœur de l'éducation. Socrate fut condamné à mort en 399 av. J.-C. pour « corruption de la jeunesse ».\n\nSon élève Platon écrivit des dialogues sur la justice, la beauté et l'État idéal. L'élève de Platon, Aristote, systématisa la logique, la biologie, l'éthique et la politique — un corpus de méthode et de savoir que les universités européennes enseigneraient encore deux mille ans plus tard.",
      "L'art et l'architecture grecs traduisaient une quête de la beauté et de la proportion idéales. Le Parthénon, au sommet de l'Acropole d'Athènes — bâti entre 447 et 432 av. J.-C. sous la direction du sculpteur Phidias — en est l'exemple parfait. Ses colonnes se renflent légèrement au milieu pour corriger les illusions d'optique, créant l'impression d'une parfaite rectitude. Des sculpteurs comme Myron et Praxitèle représentèrent le corps humain dans des poses idéalisées et naturelles, dépassant de loin la frontalité rigide des styles antérieurs.\n\nLes Jeux olympiques, fondés en 776 av. J.-C. à Olympie en l'honneur de Zeus, réunissaient tous les quatre ans des athlètes de tout le monde grec. Pendant les Jeux, les guerres étaient suspendues par une trêve sacrée. Les épreuves comprenaient la course, la lutte, le lancer du disque, la course de chars et le pentathlon. Les vainqueurs ne gagnaient qu'une couronne d'olivier — mais étaient célébrés comme des héros dans leur cité et immortalisés dans des odes par des poètes comme Pindare. Les Jeux incarnaient l'idéal grec de l'arétè : l'excellence, la vertu et l'émulation.",
      "À la fin du IVe siècle av. J.-C., les conquêtes macédoniennes portèrent la langue, la culture et les institutions grecques à travers une vaste part du monde antique — de l'Égypte à la Bactriane (l'Afghanistan actuel). Ce monde « hellénistique » abritait de magnifiques cités : Alexandrie en Égypte, avec sa légendaire bibliothèque de peut-être 500 000 rouleaux ; Antioche en Syrie ; Pergame en Anatolie. Ces centres cosmopolites mêlaient traditions grecque, perse, égyptienne et indienne.\n\nLes savants hellénistiques firent des progrès spectaculaires. Ératosthène calcula la circonférence de la Terre avec une précision remarquable à l'aide d'ombres et de géométrie. Euclide systématisa la géométrie ; Archimède calcula pi et découvrit les principes de la flottaison et du levier. Aristarque proposa même que la Terre tourne autour du Soleil — dix-sept siècles avant Copernic. Quand Rome absorba enfin les royaumes hellénistiques, elle préserva et transmit cet héritage intellectuel, faisant de la Grèce classique la source de la civilisation occidentale.",
    ],
  },
  'ancient-03': {
    de: [
      "Der Überlieferung nach wurde Rom 753 v. Chr. auf sieben Hügeln am Tiber gegründet. Nach der Vertreibung seiner Könige um 509 v. Chr. wurde Rom eine Republik, regiert von gewählten Konsuln und einem Senat aus Aristokraten. Mit der Zeit erlangten die Plebejer durch die Zwölftafelgesetze — Roms erstes schriftliches Recht — größere Rechte.\n\nRom dehnte sich stetig über Italien aus und besiegte seine Rivalen durch militärische Disziplin und geschickte Diplomatie. Um 264 v. Chr. beherrschte Rom die italische Halbinsel und richtete seinen Blick auf die weitere Mittelmeerwelt.",
      "Roms Zusammenstoß mit Karthago führte zu den drei Punischen Kriegen (264–146 v. Chr.). Der karthagische Feldherr Hannibal überquerte berühmt mit Kriegselefanten die Alpen und vernichtete 216 v. Chr. bei Cannae römische Heere. Doch Roms Widerstandskraft siegte; Karthago wurde 146 v. Chr. endgültig zerstört.\n\nDie römische Eroberung brachte großen Reichtum, aber auch soziale Spannungen. Feldherren wie Marius und Sulla befehligten persönliche, ihnen statt dem Senat ergebene Heere. Julius Cäsars militärisches Genie in Gallien machte ihn zum mächtigsten Mann Roms — bis zu seiner Ermordung an den Iden des März 44 v. Chr.",
      "Cäsars Erbe Octavian besiegte seine Rivalen und wurde 27 v. Chr. als Augustus der erste Kaiser Roms. Das augusteische Zeitalter läutete die Pax Romana ein — zwei Jahrhunderte relativer Stabilität, Wohlstand und kultureller Blüte. Das römische Straßennetz, die Aquädukte und das Rechtssystem einten ein riesiges Reich von Britannien bis Mesopotamien.\n\nAuf seinem Höhepunkt unter Kaiser Trajan umfasste Roms Reich 5 Millionen Quadratkilometer und vielleicht 70 Millionen Menschen. Doch Überdehnung, wirtschaftliche Not und militärischer Druck germanischer Stämme schwächten das Reich allmählich. 476 n. Chr. wurde der letzte weströmische Kaiser abgesetzt.",
      "Die römische Zivilisation war ebenso sehr eine Ingenieurs- wie eine politische Leistung. Die Römer bauten über 80.000 km Straßen aus gefügten Steinen. Sie erfanden den Beton, der den Bau der unbewehrten Kuppel des Pantheons — noch nach 2.000 Jahren die größte der Welt —, gewaltiger Aquädukte, die Frischwasser über Hunderte Kilometer führten, und des Kolosseums mit 80.000 Plätzen ermöglichte.\n\nDer römische Alltag ist erstaunlich vertraut. Stadtrömer lebten in mehrstöckigen Mietshäusern (insulae), kauften bei Bäckereien und Tavernen ein, besuchten öffentliche Bäder (thermae) zur Geselligkeit und wohnten Gladiatorenspielen und Wagenrennen bei. Das römische Recht, in Kaiser Justinians Corpus Juris Civilis (529 n. Chr.) systematisiert, bildet bis heute die Grundlage der Rechtssysteme in ganz Europa und Lateinamerika.",
      "Unter der Herrschaft des Augustus wurde in der römischen Provinz Judäa ein jüdischer Lehrer namens Jesus von Nazareth geboren. Um 30 n. Chr. unter dem römischen Statthalter Pontius Pilatus gekreuzigt, glaubten seine Anhänger, er sei von den Toten auferstanden. Das Christentum breitete sich rasch entlang der römischen Straßen aus und sprach besonders Sklaven, Frauen und Arme mit seiner Botschaft von Gleichheit und geistiger Erlösung an. Um 300 n. Chr. war vielleicht ein Zehntel des Reiches christlich.\n\n313 n. Chr. erließ Kaiser Konstantin das Mailänder Edikt und legalisierte das Christentum. Um 380 n. Chr. war es Staatsreligion. Die Annahme des Christentums verwandelte das Reich und die gesamte westliche Geschichte — sie prägte Bildung, Kunst, Philosophie und Recht. Als das Weströmische Reich im 5. Jahrhundert fiel, überdauerte die Kirche als wichtigste institutionelle Kontinuität zwischen antiker und mittelalterlicher Welt, bewahrte die lateinische Schriftkultur und gab Roms angesammelte Weisheit an künftige Generationen weiter.",
    ],
    fr: [
      "Selon la tradition, Rome fut fondée en 753 av. J.-C. sur sept collines au bord du Tibre. Après avoir chassé ses rois vers 509 av. J.-C., Rome devint une république gouvernée par des consuls élus et un Sénat d'aristocrates. Avec le temps, les plébéiens gagnèrent des droits grâce à la Loi des Douze Tables — le premier code écrit de Rome.\n\nRome s'étendit régulièrement à travers l'Italie, battant ses rivaux par la discipline militaire et une habile diplomatie. Vers 264 av. J.-C., Rome contrôlait la péninsule italienne et tournait son regard vers l'ensemble du monde méditerranéen.",
      "L'affrontement de Rome avec Carthage engendra les trois guerres puniques (264–146 av. J.-C.). Le général carthaginois Hannibal franchit fameusement les Alpes avec des éléphants de guerre et écrasa les armées romaines à Cannes en 216 av. J.-C. Pourtant la ténacité de Rome l'emporta ; Carthage fut finalement détruite en 146 av. J.-C.\n\nLa conquête romaine apporta de grandes richesses mais aussi des tensions sociales. Des généraux comme Marius et Sylla commandaient des armées personnelles loyales à eux plutôt qu'au Sénat. Le génie militaire de Jules César en Gaule fit de lui l'homme le plus puissant de Rome — jusqu'à son assassinat aux ides de mars 44 av. J.-C.",
      "L'héritier de César, Octave, vainquit ses rivaux et devint le premier empereur de Rome sous le nom d'Auguste en 27 av. J.-C. L'âge augustéen inaugura la Pax Romana — deux siècles de stabilité, de prospérité et de floraison culturelle relatives. Le réseau routier romain, les aqueducs et le système juridique unifièrent un vaste empire de la Bretagne à la Mésopotamie.\n\nÀ son apogée sous l'empereur Trajan, l'empire de Rome couvrait 5 millions de kilomètres carrés et comptait peut-être 70 millions d'habitants. Mais l'expansion excessive, les tensions économiques et la pression militaire des tribus germaniques affaiblirent peu à peu l'empire. En 476, le dernier empereur romain d'Occident fut déposé.",
      "La civilisation romaine fut autant une prouesse d'ingénierie que de politique. Les Romains construisirent plus de 80 000 km de routes pavées de pierres ajustées. Ils inventèrent le béton, permettant l'édification du dôme sans armature du Panthéon — encore le plus grand du monde après 2 000 ans —, de vastes aqueducs acheminant l'eau sur des centaines de kilomètres, et du Colisée pouvant accueillir 80 000 spectateurs.\n\nLa vie quotidienne romaine est étonnamment familière. Les citadins vivaient dans des immeubles à plusieurs étages (insulae), s'approvisionnaient aux boulangeries et tavernes, fréquentaient les bains publics (thermae) pour se retrouver, et assistaient aux jeux de gladiateurs et aux courses de chars. Le droit romain, systématisé dans le Corpus Juris Civilis de l'empereur Justinien (529), reste le fondement des systèmes juridiques d'Europe et d'Amérique latine à ce jour.",
      "Sous le règne d'Auguste, un maître juif nommé Jésus de Nazareth naquit dans la Judée romaine. Crucifié sous le gouverneur romain Ponce Pilate vers l'an 30, ses disciples crurent qu'il était ressuscité des morts. Le christianisme se répandit rapidement le long des routes romaines, séduisant surtout esclaves, femmes et pauvres par son message d'égalité et de rédemption spirituelle. Vers 300, peut-être 10% de l'empire était chrétien.\n\nEn 313, l'empereur Constantin promulgua l'édit de Milan, légalisant le christianisme. En 380, il était religion officielle. L'adoption du christianisme transforma l'empire et toute l'histoire occidentale — façonnant l'éducation, l'art, la philosophie et le droit. À la chute de l'Empire d'Occident au Ve siècle, l'Église survécut comme principale continuité institutionnelle entre le monde antique et le monde médiéval, préservant la culture écrite latine et transmettant la sagesse accumulée de Rome aux générations futures.",
    ],
  },
  'ancient-04': {
    de: [
      "Unter Kyros dem Großen (reg. 550–530 v. Chr.) bauten die achämenidischen Perser das größte Reich der Antike, das von Anatolien bis zum Indus-Tal reichte. Anders als viele antike Eroberer war Kyros für religiöse Toleranz bekannt — er erlaubte den jüdischen Verbannten in Babylon die Rückkehr in ihre Heimat.\n\nDareios I. gliederte das Reich in Provinzen (Satrapien) und baute die Königsstraße, die sich 2.700 km von Sardes bis Susa erstreckte und rasche Kommunikation ermöglichte. Die persische Kultur — die zoroastrische Religion, die monumentale Architektur von Persepolis und eine ausgefeilte Verwaltung — prägte alle späteren nahöstlichen Zivilisationen tief.",
      "Indiens Maurya-Reich (322–185 v. Chr.), gegründet von Chandragupta Maurya, einte als erstes den Großteil des indischen Subkontinents. Sein Enkel Ashoka (reg. 268–232 v. Chr.) wurde einer der bemerkenswertesten Herrscher der Geschichte. Nach der brutalen Eroberung von Kalinga bekehrte sich Ashoka zum Buddhismus und regierte nach dem Dharma (der sittlichen Pflicht).\n\nAshokas Felsedikte förderten Toleranz, Gewaltlosigkeit und Fürsorge. Er sandte buddhistische Missionare nach Sri Lanka, Zentralasien und Griechenland und trug so zur Verbreitung des Buddhismus in Asien bei. Die indische Mathematik — insbesondere das Konzept der Null und das Dezimalsystem — sollte später über arabische Gelehrte die Welt verwandeln.",
      "Chinas Han-Dynastie (206 v. Chr.–220 n. Chr.) beherrschte eine der ausgefeiltesten Zivilisationen der Antike. Kaiser Wu dehnte das Reich nach Zentralasien aus und begründete die Seidenstraße — Handelswege, die China mit Rom verbanden. Seide, Gewürze und Ideen flossen in beide Richtungen entlang dieser Routen.\n\nDas Han-China entwickelte Papier, den Seismographen und Gusseisen. Die konfuzianische Ethik prägte die Regierung; das Beamtenprüfungssystem — das Beamte nach Verdienst zuließ — war ein revolutionäres Konzept. Als die Han-Dynastie 220 n. Chr. fiel, zersplitterte China, doch das Han-Modell einheitlicher Reichsherrschaft blieb das Ideal aller folgenden chinesischen Dynastien.",
      "Um 1500 v. Chr. wanderten indogermanische Völker, die Arier, ins nördliche Indien ein und brachten das Sanskrit und eine komplexe polytheistische Religion mit. Die Veden — zu den ältesten heiligen Texten der Welt zählend — entstanden in dieser Zeit: Hymnen an Götter wie Indra (Krieg), Varuna (kosmische Ordnung) und Agni (Feuer). Über Jahrhunderte entwickelte sich diese vedische Religion zum Hinduismus, nahm lokale Traditionen auf und brachte reiche philosophische Schulen hervor.\n\nDie hinduistische Philosophie brachte die Upanishaden hervor — tiefgründige metaphysische Texte über das Wesen des Selbst (Atman) und die letzte Wirklichkeit (Brahman). Die Begriffe Dharma (sittliche Pflicht), Karma (Tat und Folge) und Samsara (der Kreislauf der Wiedergeburt) boten einen umfassenden Rahmen für Ethik und Kosmologie. Die Epen Mahabharata und Ramayana verankerten hinduistische Werte für Millionen in ganz Asien und bleiben bis heute lebendige kulturelle Bezugspunkte.",
      "Die Zeit der Streitenden Reiche in China (475–221 v. Chr.) war paradoxerweise eine ihrer geistig schöpferischsten Epochen. Konfuzius (551–479 v. Chr.) lehrte, dass gesellschaftliche Harmonie auf rechten Beziehungen beruhe — zwischen Herrscher und Untertan, Eltern und Kind —, geordnet durch Ritus (li), Menschlichkeit (ren) und Rechtschaffenheit (yi). Der Konfuzianismus wurde über 2.000 Jahre Chinas vorherrschende politische Philosophie.\n\nLaozi bot im Tao Te King eine gegensätzliche Sicht: Der Weg (Tao) sei eine unaussprechliche natürliche Ordnung; gute Regierung bedeute geringstes Eingreifen. Der Taoismus prägte Chinas Kunst, Medizin und Spiritualität zutiefst. Der Legalismus vertrat das Gegenteil — Han Feizi argumentierte, Herrscher sollten mit strengen Gesetzen und harten Strafen die Gesellschaft lenken. Die Qin-Dynastie einte China 221 v. Chr. nach legalistischen Grundsätzen unter dem ersten Kaiser Qin Shihuangdi, der die Große Mauer und ein Heer aus Terrakotta-Kriegern zum Schutz seines prächtigen Grabes errichten ließ.",
    ],
    fr: [
      "Sous Cyrus le Grand (r. 550–530 av. J.-C.), les Perses achéménides bâtirent le plus grand empire de l'Antiquité, s'étendant de l'Anatolie à la vallée de l'Indus. Contrairement à bien des conquérants antiques, Cyrus était réputé pour sa tolérance religieuse — il autorisa les exilés juifs de Babylone à regagner leur patrie.\n\nDarius Ier organisa l'empire en provinces (satrapies) et bâtit la Route royale longue de 2 700 km, de Sardes à Suse, permettant une communication rapide. La culture perse — le zoroastrisme, l'architecture monumentale de Persépolis et une administration sophistiquée — influença profondément toutes les civilisations ultérieures du Proche-Orient.",
      "L'Empire maurya de l'Inde (322–185 av. J.-C.), fondé par Chandragupta Maurya, fut le premier à unifier l'essentiel du sous-continent indien. Son petit-fils Ashoka (r. 268–232 av. J.-C.) devint l'un des souverains les plus remarquables de l'histoire. Après la brutale conquête du Kalinga, Ashoka se convertit au bouddhisme et gouverna selon le dharma (le devoir moral).\n\nLes édits sur roche d'Ashoka prônaient la tolérance, la non-violence et le bien-être. Il envoya des missionnaires bouddhistes au Sri Lanka, en Asie centrale et en Grèce, contribuant à répandre le bouddhisme à travers l'Asie. Les mathématiques indiennes — en particulier le concept du zéro et le système décimal — transformeraient plus tard le monde par l'intermédiaire des savants arabes.",
      "La dynastie Han de Chine (206 av. J.-C.–220 ap. J.-C.) régna sur l'une des civilisations les plus raffinées de l'Antiquité. L'empereur Wu étendit l'empire jusqu'en Asie centrale et établit la route de la Soie — des voies reliant la Chine à Rome. Soie, épices et idées circulaient dans les deux sens le long de ces routes.\n\nLa Chine des Han inventa le papier, le sismographe et la fonte. L'éthique confucéenne façonna le gouvernement ; le système des examens mandarinaux — admettant les fonctionnaires au mérite — était une idée révolutionnaire. À la chute des Han en 220, la Chine se morcela, mais le modèle Han d'un empire unifié demeura l'idéal de toutes les dynasties chinoises suivantes.",
      "Vers 1500 av. J.-C., des peuples indo-européens appelés Aryens migrèrent vers le nord de l'Inde, apportant le sanskrit et une religion polythéiste complexe. Les Védas — parmi les plus anciens textes sacrés du monde — furent composés à cette époque : hymnes à des dieux comme Indra (guerre), Varuna (ordre cosmique) et Agni (feu). Au fil des siècles, cette religion védique évolua en hindouisme, intégrant des traditions locales et développant de riches écoles philosophiques.\n\nLa philosophie hindoue produisit les Upanishads — textes métaphysiques profonds explorant la nature du soi (Atman) et de la réalité ultime (Brahman). Les concepts de dharma (devoir moral), de karma (action et conséquence) et de samsara (le cycle des renaissances) offraient un cadre complet d'éthique et de cosmologie. Les poèmes épiques du Mahabharata et du Ramayana ancrèrent les valeurs hindoues pour des millions de gens à travers l'Asie et demeurent des références culturelles vivantes.",
      "L'ère des Royaumes combattants en Chine (475–221 av. J.-C.) fut paradoxalement l'une de ses périodes les plus créatives sur le plan intellectuel. Confucius (551–479 av. J.-C.) soutenait que l'harmonie sociale reposait sur des relations justes — entre souverain et sujet, parent et enfant — régies par le rite (li), la bienveillance (ren) et la droiture (yi). Le confucianisme devint la philosophie politique dominante de la Chine pendant plus de 2 000 ans.\n\nLaozi offrit une vision contraire dans le Tao Tö King : la Voie (Tao) était un ordre naturel ineffable ; bien gouverner, c'était intervenir le moins possible. Le taoisme façonna profondément l'art, la médecine et la spiritualité chinois. Le légisme prit le parti inverse — Han Feizi soutenait que les souverains devaient recourir à des lois strictes et à des châtiments sévères. La dynastie Qin unifia la Chine en 221 av. J.-C. selon les principes légistes sous le premier empereur, Qin Shi Huang, qui édifia la Grande Muraille et une armée de soldats en terre cuite pour garder son tombeau spectaculaire.",
    ],
  },
  'ancient-05': {
    de: [
      "Im alten Ägypten waren Politik und Religion eins. Der Pharao war nicht bloß König, sondern ein lebender Gott — die irdische Verkörperung des Horus, des Falkengottes des Himmels — und verschmolz nach dem Tod mit Osiris, dem Herrscher des Jenseits. Dieses göttliche Königtum war über 3.000 Jahre der Grundstein der ägyptischen Zivilisation.\n\nDie Autorität des Pharaos war absolut. Als Mittler zwischen Göttern und Menschen vollzog er die wesentlichen Rituale, die Maat erhielten — die kosmische Ordnung, Wahrheit und Gerechtigkeit. Ohne Maat würde der Nil nicht anschwellen, die Ernten würden versagen und das Chaos würde herrschen. Dieser Glaube verlieh den Pharaonen unangefochtene Legitimität und bewog die Untertanen, ihr Leben der Arbeit an königlichen Projekten zu widmen, darunter der Bau von Monumenten, die ewig währen sollten.",
      "Die Ägypter waren zutiefst mit dem Tod beschäftigt — nicht aus Morbidität, sondern aus leidenschaftlichem Glauben an das ewige Leben. Die über Jahrtausende verfeinerte Mumifizierung sollte den Körper bewahren, damit die Seele (ka) zu ihm zurückkehren konnte. Einbalsamierer entfernten die Organe, behandelten den Leib 40 Tage mit Natronsalz, wickelten ihn in Leinen und umgaben ihn mit schützenden Amuletten.\n\nDer Verstorbene wurde dann durch die Duat — die Unterwelt — geleitet, mit Sprüchen aus dem Totenbuch. In der Halle der zwei Wahrheiten wog der Gott Anubis das Herz gegen die Feder der Maat. Ein von Sünde schweres Herz wurde vom Ungeheuer Ammit verschlungen; ein federleichtes Herz gelangte ins Paradies des Binsengefildes. Diese ausgefeilte Theologie trieb Investitionen in Grabkunst, Grabbau und Ritualtexte voran — und machte das alte Ägypten zu einer der reichhaltigsten dokumentierten Zivilisationen der Geschichte.",
      "Die Große Pyramide von Giza, um 2560 v. Chr. für Pharao Cheops erbaut, besteht aus etwa 2,3 Millionen Steinblöcken von je 2,5–15 Tonnen. Ohne Eisenwerkzeuge, Flaschenzüge oder Räder errichtet, war sie 3.800 Jahre das höchste Bauwerk der Welt. Die Präzision ist verblüffend: Die Basis ist auf 2,1 Zentimeter genau waagerecht, und die vier Seiten sind mit einem Fehler von weniger als 0,05 Grad an den Himmelsrichtungen ausgerichtet.\n\nWie gelang das? Tausende gelernte Arbeiter — keine Sklaven, wie lange angenommen, sondern bezahlte Kräfte, die Brot, Bier, ärztliche Versorgung und ein Begräbnis nahe dem Pharao erhielten — in wechselnden Teams organisiert. Die Archäologie hat die Arbeiterdörfer freigelegt, ihre Bäckereien und Brauereien, ihre Graffiti mit dem Prahlen über ihre Kolonnen. Die Pyramiden wurden nicht von gebrochenen Menschen gebaut, sondern von einer Zivilisation mit außerordentlicher Organisationskraft, getragen von echter religiöser Hingabe.",
      "Das ägyptische Pantheon umfasste Hunderte von Gottheiten, oft mit Tierköpfen dargestellt, die ihre göttlichen Eigenschaften verkörperten. Ra, der Sonnengott, segelte täglich in seiner Sonnenbarke über den Himmel und nachts durch die Unterwelt, im Kampf mit der Schlange Apophis. Osiris, von seinem eifersüchtigen Bruder Seth ermordet und zerstückelt, wurde von seiner treuen Gattin Isis auferweckt — ein Mythos von Tod und Erneuerung, der über Jahrtausende nachhallte.\n\nIsis wurde eine der beliebtesten Göttinnen der antiken Welt, ihr Kult breitete sich schließlich über das ganze Römische Reich aus. Thoth, der ibisköpfige Gott der Schrift und des Wissens, galt als Erfinder der Hieroglyphen. Sachmet, die löwenköpfige Kriegsgöttin, konnte Seuchen senden wie heilen. Diese Götter waren keine fernen Abstraktionen, sondern tätige Teilnehmer des Alltags — sie schützten Mütter bei der Geburt, leiteten die Toten und erhielten die himmlische Ordnung, die den Nil pünktlich anschwellen ließ.",
      "Ägyptens Neues Reich (ca. 1550–1070 v. Chr.) war seine mächtigste Epoche. Pharaonen wie Thutmosis III. eroberten ein Reich von Nubien bis Syrien. Ramses II. (reg. 1279–1213 v. Chr.), der 66 Jahre herrschte und über 100 Kinder zeugte, schloss nach der Schlacht bei Kadesch den ältesten erhaltenen Friedensvertrag der Geschichte mit den Hethitern.\n\nÄgyptens letzter Akt gehört Kleopatra VII. (reg. 51–30 v. Chr.), der letzten der ptolemäischen Dynastie. Eine brillante Sprachkundige, die neun Sprachen sprach, schmiedete sie strategische Bündnisse mit Julius Cäsar und Marcus Antonius, um Ägyptens Unabhängigkeit gegen Rom zu wahren. Als Antonius' Streitkräfte 31 v. Chr. bei Actium geschlagen wurden, wählte Kleopatra den Tod statt der Unterwerfung. Mit ihr endeten 3.000 Jahre pharaonischer Zivilisation — doch Ägyptens Kunst, Religion und Mythologie faszinierten und prägten weiterhin Kulturen in aller Welt.",
    ],
    fr: [
      "Dans l'Égypte antique, politique et religion ne faisaient qu'un. Le pharaon n'était pas un simple roi mais un dieu vivant — l'incarnation terrestre d'Horus, dieu-faucon du ciel — et, à sa mort, il se fondait dans Osiris, maître de l'au-delà. Cette royauté divine fut la pierre angulaire de la civilisation égyptienne pendant plus de 3 000 ans.\n\nL'autorité du pharaon était totale. Intermédiaire entre les dieux et les hommes, il accomplissait les rituels essentiels qui maintenaient la Maât — l'ordre cosmique, la vérité et la justice. Sans la Maât, le Nil ne déborderait pas, les récoltes échoueraient et le chaos régnerait. Cette croyance conférait aux pharaons une légitimité incontestée et poussait les sujets à consacrer une vie de labeur aux projets royaux, dont l'édification de monuments conçus pour durer éternellement.",
      "Les Égyptiens étaient profondément préoccupés par la mort — non par morbidité, mais par une croyance passionnée en la vie éternelle. La momification, affinée sur des millénaires, visait à préserver le corps afin que l'âme (ka) puisse y revenir. Les embaumeurs retiraient les organes, traitaient le corps au natron pendant 40 jours, l'enveloppaient de lin et l'entouraient d'amulettes protectrices.\n\nLe défunt était ensuite guidé à travers la Douat — le monde souterrain — par les formules du Livre des morts. À la Salle des Deux Vérités, le dieu Anubis pesait le cœur contre la plume de Maât. Un cœur lourd de péchés était dévoré par le monstre Ammit ; un cœur léger comme une plume entrait au paradis du Champ des roseaux. Cette théologie élaborée stimula l'investissement dans l'art funéraire, la construction des tombes et les textes rituels — faisant de l'Égypte antique l'une des civilisations les mieux documentées de l'histoire.",
      "La Grande Pyramide de Gizeh, bâtie pour le pharaon Khéops vers 2560 av. J.-C., se compose d'environ 2,3 millions de blocs de pierre pesant chacun 2,5 à 15 tonnes. Construite sans outils de fer, poulies ni roues, elle resta 3 800 ans le plus haut édifice du monde. La précision est stupéfiante : la base est de niveau à 2,1 centimètres près, et les quatre faces sont alignées sur les points cardinaux avec une erreur inférieure à 0,05 degré.\n\nComment y parvint-on ? Des milliers d'ouvriers qualifiés — non des esclaves, comme on l'a longtemps cru, mais des travailleurs payés qui recevaient pain, bière, soins médicaux et une sépulture près du pharaon — organisés en équipes tournantes. L'archéologie a révélé les villages ouvriers, leurs boulangeries et brasseries, leurs graffitis vantant leurs équipes. Les pyramides ne furent pas bâties par des gens brisés mais par une civilisation d'une extraordinaire capacité d'organisation, animée d'une dévotion religieuse sincère.",
      "Le panthéon égyptien comptait des centaines de divinités, souvent représentées à tête d'animal traduisant leurs qualités divines. Rê, dieu solaire, voguait chaque jour dans sa barque à travers le ciel et chaque nuit dans le monde souterrain, combattant le serpent Apophis. Osiris, assassiné et démembré par son frère jaloux Seth, fut ressuscité par son épouse dévouée Isis — mythe de mort et de renouveau résonnant à travers les millénaires.\n\nIsis devint l'une des déesses les plus aimées du monde antique, son culte se répandant jusque dans tout l'Empire romain. Thot, dieu à tête d'ibis de l'écriture et du savoir, passait pour l'inventeur des hiéroglyphes. Sekhmet, déesse lionne de la guerre, pouvait à la fois envoyer les fléaux et les guérir. Ces dieux n'étaient pas de lointaines abstractions mais des acteurs de la vie quotidienne — protégeant les mères en couches, guidant les défunts et maintenant l'ordre céleste qui faisait déborder le Nil à date fixe.",
      "Le Nouvel Empire égyptien (v. 1550–1070 av. J.-C.) fut son ère la plus puissante. Des pharaons comme Thoutmôsis III conquirent un empire allant de la Nubie à la Syrie. Ramsès II (r. 1279–1213 av. J.-C.), qui régna 66 ans et engendra plus de 100 enfants, signa le plus ancien traité de paix conservé de l'histoire avec les Hittites après la bataille de Qadesh.\n\nLe dernier acte de l'Égypte revient à Cléopâtre VII (r. 51–30 av. J.-C.), dernière de la dynastie lagide. Brillante polyglotte parlant neuf langues, elle noua des alliances stratégiques avec Jules César et Marc Antoine pour préserver l'indépendance égyptienne face à Rome. Quand les forces d'Antoine furent vaincues à Actium en 31 av. J.-C., Cléopâtre choisit la mort plutôt que la soumission. Avec elle s'achevèrent 3 000 ans de civilisation pharaonique — mais l'art, la religion et la mythologie de l'Égypte continuèrent de fasciner et d'influencer les cultures du monde entier.",
    ],
  },
  'ancient-06': {
    de: [
      "Die Phönizier bewohnten einen schmalen Küstenstreifen des östlichen Mittelmeers — etwa den heutigen Libanon —, eingezwängt zwischen Meer und Libanongebirge. Was ihnen an Land fehlte, gewannen sie an maritimem Genie. Ihre großen Hafenstädte — Tyros, Sidon, Byblos, Beirut — zählten zu den wohlhabendsten Handelszentren der Antike.\n\nDie Griechen nannten sie „Phoinikes“ — das Purpurvolk — nach Phöniziens berühmtestem Erzeugnis: einem leuchtend purpurroten Farbstoff aus dem Schleim der Purpurschnecke. Schon eine kleine Menge erforderte Tausende Schnecken und stank während der Verarbeitung nach Fäulnis; der fertige Farbstoff war seltener als Gold. Nur Könige und Hohepriester konnten sich phönizische Purpurgewänder leisten. Die Farbe „Königspurpur“ bewahrt bis heute ihre Verbindung zu Macht und Reichtum — ein Erbe phönizischen Handels über dreitausend Jahre hinweg.",
      "Der folgenreichste Beitrag der Phönizier zur Zivilisation war weder Purpur noch Handelsschifffahrt, sondern die Schrift. Um 1050 v. Chr. entwickelten sie eine vereinfachte Buchstabenschrift aus 22 Konsonanten — eine revolutionäre Vereinfachung der komplexen Keilschrift- und Hieroglyphensysteme, deren Beherrschung jahrelange Fachausbildung verlangt hatte. Der Lehrling eines phönizischen Kaufmanns konnte das System in Wochen lernen.\n\nDiese Praktikabilität machte es unwiderstehlich. Die Griechen übernahmen das phönizische Alphabet um das 9. Jahrhundert v. Chr. und fügten Vokale hinzu — der Vorfahre jedes westlichen Alphabets. Aus dem Griechischen wurde das Lateinische; aus dem Lateinischen Italienisch, Französisch, Spanisch, Englisch und Dutzende weitere Sprachen. Die aramäische Fassung breitete sich ostwärts aus und wurde zur Mutter von Hebräisch, Arabisch und den Schriften Südasiens. Jedes Mal, wenn Sie lesen oder schreiben, nutzen Sie ein System, das von phönizischen Kaufleuten abstammt, die eine effiziente Art brauchten, Ladelisten und Geschäfte festzuhalten. Keine einzelne kulturelle Erfindung hatte weiteren Einfluss auf die Menschheitsgeschichte.",
      "Phönizische Handelsschiffe fuhren, wohin es Gewinn zu machen gab. Sie erschlossen Routen westwärts durchs Mittelmeer, um Sizilien und Sardinien, durch die Straße von Gibraltar — die sie „Säulen des Melqart“ nannten — und entlang der Atlantikküsten Europas und Afrikas. Ihre Handelsschiffe, robuste rundbäuchige „Hippoi“ (nach ihren pferdekopfförmigen Bugen benannt), konnten Ladungen von 30–50 Tonnen tragen und navigierten nach Sternen und überliefertem Wissen.\n\nDie Phönizier gründeten Handelsposten und Kolonien im ganzen Mittelmeer: auf Zypern, Sardinien, Malta, Sizilien, den Balearen und an Spaniens Küste. Sie handelten mit kanaanäischem Wein und Öl, ägyptischem Leinen, mesopotamischen Textilien, zyprischem Kupfer, spanischem Silber und afrikanischem Elfenbein. Ihre Handelsnetze waren umfassender als die jeder früheren Zivilisation und schufen die Vorlage des Mittelmeerhandels, die Griechen, Karthager und Römer später übernehmen und ausweiten sollten.",
      "Um 814 v. Chr. führte der Überlieferung nach Königin Dido von Tyros eine Gruppe von Verbannten, um Karthago („Neustadt“) auf einer Landzunge der nordafrikanischen Küste beim heutigen Tunis zu gründen. Ob die Sagengründung zutrifft oder nicht — Karthago überflügelte rasch alle phönizischen Mutterstädte. Seine dreifachen Häfen — einer für den Handel, einer für die Kriegsflotte, einer für die königliche Flotte — konnten zugleich 220 Kriegsschiffe fassen.\n\nBis zum 4. Jahrhundert v. Chr. beherrschte Karthago den Handel des westlichen Mittelmeers und regierte ein Handelsreich, das Nordafrika, Spanien, Sardinien und Sizilien umfasste. Sein Söldnerheer — numidische Reiter, spanische Infanterie, griechische Offiziere — war die furchterregendste Macht des westlichen Mittelmeers. Karthagos Zusammenstoß mit der aufsteigenden Römischen Republik in den drei Punischen Kriegen (264–146 v. Chr.) sollte die Zivilisation verändern. Rom setzte sich schließlich durch — es machte Karthago 146 v. Chr. dem Erdboden gleich —, doch erst, nachdem Hannibals Genie Rom an den Rand der Vernichtung gebracht hatte. Der Kampf zwischen Rom und Karthago prägte die gesamte Zukunft der westlichen Zivilisation.",
      "Die Phönizier verschwanden als eigenständiges Volk, aufgesogen von der sich ausdehnenden hellenistischen und später römischen Welt, doch ihr Erbe erwies sich als unzerstörbar. Das von jeder Zivilisation, die ihm begegnete, abgewandelte Alphabet wurde zum Werkzeug, mit dem menschliches Wissen über Jahrtausende festgehalten und übermittelt wurde. Ohne die phönizische Schrift gäbe es keinen Homer, keine Bibel, keine klassische Philosophie, keine wissenschaftliche Literatur.\n\nPhönizische Seemannskunst vermaß die Welt: Griechische Geographen berichteten später, phönizische Seeleute, um 600 v. Chr. von Ägyptens Pharao Necho II. beauftragt, hätten den ganzen Kontinent Afrika umsegelt — eine Leistung, die Europäer erst mit Vasco da Gama 1488 wiederholten. Ihre Beobachtung, dass die Sonne während des südlichen Teils der Reise in ihrem Norden stand, hielt Herodot für unglaubwürdig — doch gerade dieses Detail überzeugte moderne Gelehrte von der Echtheit des Berichts. In ihrem rastlosen, kaufmännischen, seefahrenden Geist nahmen die Phönizier etwas ausgesprochen Modernes vorweg: die Idee, dass die Welt da ist, um erkundet, behandelt und verbunden zu werden.",
    ],
    fr: [
      "Les Phéniciens occupaient une étroite bande côtière de la Méditerranée orientale — à peu près le Liban actuel — coincée entre la mer et les monts du Liban. Ce qui leur manquait en terres, ils le gagnaient en génie maritime. Leurs grandes cités portuaires — Tyr, Sidon, Byblos, Beyrouth — comptaient parmi les centres commerciaux les plus prospères de l'Antiquité.\n\nLes Grecs les appelaient « Phoinikes » — le peuple pourpre — d'après le produit le plus célèbre de la Phénicie : une teinture d'un pourpre cramoisi vif extraite du mucus du murex. En produire même une petite quantité exigeait des milliers de coquillages et dégageait une puanteur de pourriture ; la teinture finie était plus rare que l'or. Seuls rois et grands prêtres pouvaient s'offrir des robes de pourpre phénicienne. La couleur « pourpre royale » conserve à ce jour son lien avec le pouvoir et la richesse — héritage du commerce phénicien sur trois mille ans.",
      "La contribution la plus décisive des Phéniciens à la civilisation ne fut ni la teinture pourpre ni la marine marchande, mais l'écriture. Vers 1050 av. J.-C., ils mirent au point une écriture alphabétique simplifiée de 22 consonnes — simplification révolutionnaire des systèmes cunéiforme et hiéroglyphique dont la maîtrise avait exigé des années de formation spécialisée. L'apprenti d'un marchand phénicien pouvait apprendre le système en quelques semaines.\n\nCette commodité le rendit irrésistible. Les Grecs adoptèrent l'alphabet phénicien vers le IXe siècle av. J.-C., ajoutant les voyelles pour créer l'ancêtre de tout alphabet occidental. Le grec devint le latin ; le latin devint l'italien, le français, l'espagnol, l'anglais et des dizaines d'autres langues. La version araméenne se répandit vers l'est, devenant la mère de l'hébreu, de l'arabe et des écritures d'Asie du Sud. Chaque fois que vous lisez ou écrivez, vous utilisez un système hérité de marchands phéniciens qui avaient besoin d'un moyen efficace de noter manifestes de cargaison et transactions. Aucune invention culturelle unique n'a eu d'impact plus vaste sur l'histoire humaine.",
      "Les navires de commerce phéniciens s'aventuraient partout où il y avait profit à faire. Ils ouvrirent des routes vers l'ouest à travers la Méditerranée, autour de la Sicile et de la Sardaigne, par le détroit de Gibraltar — qu'ils appelaient les « colonnes de Melqart » — et le long des côtes atlantiques d'Europe et d'Afrique. Leurs vaisseaux marchands, robustes « hippoi » à coque ronde (nommés d'après leurs proues en tête de cheval), pouvaient porter 30 à 50 tonnes de fret, naviguant aux étoiles et au savoir transmis de capitaine en capitaine.\n\nLes Phéniciens établirent comptoirs et colonies à travers la Méditerranée : à Chypre, en Sardaigne, à Malte, en Sicile, aux Baléares et sur la côte espagnole. Ils échangeaient vin et huile de Canaan, lin égyptien, textiles mésopotamiens, cuivre chypriote, argent espagnol et ivoire africain. Leurs réseaux commerciaux étaient plus vastes que ceux de toute civilisation antérieure, créant le modèle du commerce méditerranéen que Grecs, Carthaginois et Romains hériteraient et étendraient ensuite.",
      "Vers 814 av. J.-C., selon la tradition, la reine Didon de Tyr conduisit un groupe d'exilés pour fonder Carthage (« ville neuve ») sur un promontoire de la côte nord-africaine près de l'actuelle Tunis. Que la fondation légendaire soit exacte ou non, Carthage dépassa rapidement toutes les cités-mères phéniciennes. Ses ports triples — un pour le commerce, un pour la marine, un pour la flotte royale — pouvaient accueillir simultanément 220 navires de guerre.\n\nAu IVe siècle av. J.-C., Carthage contrôlait le commerce de la Méditerranée occidentale, régnant sur un empire commercial englobant l'Afrique du Nord, l'Espagne, la Sardaigne et la Sicile. Son armée de mercenaires — cavalerie numide, infanterie espagnole, officiers grecs — était la force la plus redoutable de la Méditerranée occidentale. L'affrontement de Carthage avec la République romaine montante lors des trois guerres puniques (264–146 av. J.-C.) allait changer le cours de la civilisation. Rome finit par l'emporter — rasant Carthage en 146 av. J.-C. — mais seulement après que le génie d'Hannibal eut mené Rome au bord de la destruction. La lutte entre Rome et Carthage façonna tout l'avenir de la civilisation occidentale.",
      "Les Phéniciens disparurent comme peuple distinct, absorbés dans les mondes hellénistique puis romain en expansion, mais leur héritage se révéla indestructible. L'alphabet, modifié par chaque civilisation qui le rencontra, devint l'outil par lequel le savoir humain fut consigné et transmis à travers les millénaires. Sans l'écriture phénicienne, il n'y aurait ni Homère, ni Bible, ni philosophie classique, ni littérature scientifique.\n\nLa marine phénicienne cartographia le monde : des géographes grecs rapportèrent plus tard que des marins phéniciens, commandités par le pharaon Néchao II d'Égypte vers 600 av. J.-C., firent le tour du continent africain — exploit que les Européens ne répétèrent qu'avec Vasco de Gama en 1488. Leur observation que le soleil paraissait au nord durant la partie sud du voyage fut jugée incroyable par Hérodote — pourtant c'est précisément ce détail qui convainquit les savants modernes de l'authenticité du récit. Dans leur esprit inquiet, marchand et marin, les Phéniciens préfiguraient quelque chose de nettement moderne : l'idée que le monde existe pour être exploré, échangé et relié.",
    ],
  },
  'ancient-07': {
    de: [
      "Nördlich des Olymp, jenseits der Stadtstaaten, die sich für das Zentrum der Zivilisation hielten, lag Makedonien — ein raues Königreich aus Bergland-Hirten, Tiefland-Bauern und harten Reiter-Aristokraten. Die Südgriechen taten die Makedonen als Halbbarbaren ab, die ihren Wein unvermischt tranken und Politik mit Jagdspeeren regelten. Doch das Königreich besaß, was den zersplitterten Stadtstaaten fehlte: Holz, Goldminen, weite Reiterebenen und ein einziges Königshaus — die Argeaden —, das seine Abstammung von Herakles herleitete.\n\nVon der Hauptstadt Pella und dem alten Königssitz Aigai, wo die Könige bestattet wurden, sah Makedonien zu, wie sich die griechische Welt in endlosen Kriegen zwischen Athen, Sparta und Theben erschöpfte. 359 v. Chr. erbte ein dreiundzwanzigjähriger Prinz namens Philipp ein zerschlagenes Königreich am Rand des Zusammenbruchs — und machte es binnen zweier Jahrzehnte zur furchtbarsten Militärmacht der Erde.",
      "Philipp II. begriff, dass Schlachten durch Organisation gewonnen werden, nicht durch Heldentum. Er bewaffnete seine Infanterie mit der Sarissa — einem bis zu sechs Meter langen Spieß — und drillte sie zu einer Phalanx, die eine undurchdringliche Hecke aus Eisenspitzen bot. Diesem Amboss stellte er einen Hammer zur Seite: die Hetairenreiterei, die besten Stoßreiter der Zeit. Er vervollkommnete die Belagerungskunst, professionalisierte den Sold und heiratete strategisch quer über den Balkan.\n\nEine nach der anderen verleibte Philipp sich die Goldminen Thrakiens, die Häfen der Chalkidiki und Thessaliens Reiterland ein. Als Athen und Theben sich schließlich 338 v. Chr. bei Chaironeia gegen ihn verbündeten, zerschmetterte sein Heer sie an einem einzigen Nachmittag — sein achtzehnjähriger Sohn Alexander führte den entscheidenden Reiterangriff. Philipp zwang die griechischen Staaten unter seiner Führung in den Korinthischen Bund und rüstete zu einer großen Invasion Persiens. 336 v. Chr., bei der Hochzeit seiner Tochter in Aigai, wurde er von seinem eigenen Leibwächter ermordet — und Thron, Heer und das Persien-Vorhaben gingen an Alexander über.",
      "Alexander setzte 334 v. Chr. mit etwa 40.000 Mann nach Asien über und schleuderte einen Speer an den Strand, um den Kontinent als „speererworbenes“ Land zu beanspruchen. Am Fluss Granikos zerbrach er das erste gegen ihn gesandte persische Heer. Bei Issos (333 v. Chr.) schlug er König Dareios III. selbst in die Flucht und nahm die königliche Familie gefangen. Dareios' Angebot der halben Reichshälfte lehnte er ab — „Ich würde annehmen“, sagte sein General Parmenion, „wäre ich Alexander“; „Das würde ich auch“, erwiderte Alexander, „wäre ich Parmenion“ — und wandte sich stattdessen nach Süden.\n\nTyros, die uneinnehmbare Inselfestung, fiel nach siebenmonatiger Belagerung, in der Alexander einen Damm durchs Meer baute. Ägypten empfing ihn als Befreier und krönte ihn zum Pharao; am Nildelta zeichnete er die Straßen Alexandrias vor, der größten der zwanzig Städte, die seinen Namen tragen sollten. Dann, bei Gaugamela 331 v. Chr., vielleicht fünf zu eins unterlegen, vernichtete er Dareios' letztes großes Heer. Babylon, Susa und Persepolis — mit seinem Schatz von 120.000 Talenten — fielen nacheinander. Das Reich des Kyros war sein.",
      "Die meisten Eroberer hätten aufgehört. Alexander marschierte weiter — durch den Hindukusch, über Baktrien und Sogdien, jagte Dareios' Mörder und schlug in drei Jahren brutaler Bergkriegsführung einen Aufstand nach dem anderen nieder. Er heiratete die baktrische Adelige Roxane, legte persische Hoftracht an und begann, unterworfene Völker als zu regierende Untertanen statt als zu plündernde Feinde zu behandeln — eine Politik, die seine makedonischen Veteranen zunehmend verdross.\n\n326 v. Chr. stieg er in den Punjab hinab und besiegte König Poros und seine Kriegselefanten am Fluss Hydaspes, in vielleicht seiner taktisch brillantesten Schlacht. Er drängte ostwärts zum Ganges — doch am Fluss Hyphasis weigerte sich sein erschöpftes Heer, acht Jahre und 20.000 Kilometer von der Heimat entfernt, einen weiteren Schritt zu tun. Zum einzigen Mal in seinem Leben wurde Alexander besiegt — von den eigenen Männern. Der Rückzug durch die gedrosische Wüste tötete mehr seiner Soldaten als alle seine Schlachten zusammen.",
      "Zurück in Babylon, bei der Planung einer Arabien-Expedition, verfiel Alexander nach einer durchzechten Nacht plötzlich in Fieber. Am 11. Juni 323 v. Chr. starb er im Palast Nebukadnezars, einen Monat vor seinem dreiunddreißigsten Geburtstag. Auf dem Sterbebett gefragt, wem er das Reich hinterlasse, flüsterte er angeblich „dem Stärksten“. Seine Generäle — die Diadochen — kamen dem nach und zerrissen das Reich in vierzig Jahren Krieg: Ptolemaios nahm Ägypten, Seleukos nahm Asien, Antigonos' Erben nahmen Makedonien selbst.\n\nDoch die Eroberung überlebte den Eroberer. Griechisch wurde die gemeinsame Sprache von der Adria bis nach Afghanistan; griechische Städte, Theater und Gymnasien sprossen über drei Kontinente; Alexandrias Bibliothek und Museum machten Ägypten zur geistigen Hauptstadt der Welt. Diese hellenistische Zivilisation — griechische Kultur verschmolzen mit persischen, ägyptischen und indischen Traditionen — formte die Welt, die Rom erben würde, die Welt, in der das Neue Testament geschrieben werden sollte. Der Junge aus Pella hatte die antike Welt nicht bloß erobert; er hatte sie neu verdrahtet.",
    ],
    fr: [
      "Au nord du mont Olympe, au-delà des cités-États qui se croyaient le centre de la civilisation, s'étendait la Macédoine — un rude royaume de bergers montagnards, de paysans des plaines et d'aristocrates cavaliers. Les Grecs du sud méprisaient les Macédoniens, ces demi-barbares qui buvaient leur vin pur et réglaient la politique à coups d'épieux de chasse. Pourtant le royaume possédait ce qui manquait aux cités morcelées : bois, mines d'or, vastes plaines à cavalerie, et une seule maison royale — les Argéades — qui se disait descendue d'Héraklès.\n\nDepuis la capitale de Pella et l'ancien siège royal d'Aigéai où l'on enterrait les rois, la Macédoine regardait le monde grec s'épuiser en guerres sans fin entre Athènes, Sparte et Thèbes. En 359 av. J.-C., un prince de vingt-trois ans nommé Philippe hérita d'un royaume meurtri au bord de l'effondrement — et en deux décennies en fit la plus redoutable puissance militaire de la terre.",
      "Philippe II comprit que les batailles se gagnent par l'organisation, non par l'héroïsme. Il arma son infanterie de la sarisse — une pique de six mètres — et la dressa en phalange offrant une haie impénétrable de pointes de fer. À cette enclume il adjoignit un marteau : la cavalerie des compagnons, les meilleurs cavaliers de choc de l'époque. Il perfectionna l'art du siège, professionnalisa la solde et se maria stratégiquement à travers les Balkans.\n\nUne à une, Philippe absorba les mines d'or de Thrace, les ports de Chalcidique et les terres à cavalerie de Thessalie. Quand Athènes et Thèbes se liguèrent enfin contre lui à Chéronée en 338 av. J.-C., son armée les brisa en un seul après-midi — son fils Alexandre, âgé de dix-huit ans, menant la charge de cavalerie décisive. Philippe força les États grecs à entrer dans la Ligue de Corinthe sous sa direction et prépara une grande invasion de la Perse. En 336 av. J.-C., aux noces de sa fille à Aigéai, il fut assassiné par son propre garde du corps — et le trône, l'armée et le projet perse passèrent à Alexandre.",
      "Alexandre passa en Asie en 334 av. J.-C. avec environ 40 000 hommes, jetant une lance sur le rivage pour revendiquer le continent comme terre « conquise par la lance ». Au fleuve Granique, il brisa la première armée perse envoyée contre lui. À Issos (333 av. J.-C.), il mit en déroute le roi Darius III lui-même, capturant la famille royale. Refusant l'offre par Darius de la moitié de l'empire — « J'accepterais, dit son général Parménion, si j'étais Alexandre » ; « Moi aussi, répliqua Alexandre, si j'étais Parménion » — il obliqua vers le sud.\n\nTyr, l'imprenable forteresse insulaire, tomba après un siège de sept mois au cours duquel Alexandre bâtit une chaussée à travers la mer. L'Égypte l'accueillit en libérateur et le couronna pharaon ; sur le delta du Nil, il traça les rues d'Alexandrie, la plus grande des vingt villes qui porteraient son nom. Puis, à Gaugamèles en 331 av. J.-C., en infériorité peut-être de cinq contre un, il anéantit la dernière grande armée de Darius. Babylone, Suse et Persépolis — avec son trésor de 120 000 talents — tombèrent tour à tour. L'empire de Cyrus était sien.",
      "La plupart des conquérants se seraient arrêtés. Alexandre poursuivit — à travers l'Hindou Kouch, la Bactriane et la Sogdiane, traquant les meurtriers de Darius et écrasant révolte sur révolte en trois ans de guerre de montagne brutale. Il épousa la noble bactrienne Roxane, adopta le costume de cour perse et commença à traiter les peuples conquis comme des sujets à gouverner plutôt que des ennemis à piller — politiques que ses vétérans macédoniens supportaient de plus en plus mal.\n\nEn 326 av. J.-C., il descendit dans le Pendjab et vainquit le roi Pôros et ses éléphants de guerre au fleuve Hydaspe, dans sa bataille peut-être la plus brillante sur le plan tactique. Il poussa vers l'est en direction du Gange — mais au fleuve Hyphase, son armée épuisée, à huit ans et 20 000 kilomètres de chez elle, refusa d'avancer d'un pas de plus. Pour la seule fois de sa vie, Alexandre fut vaincu — par ses propres hommes. La retraite à travers le désert de Gédrosie tua plus de ses soldats que toutes ses batailles réunies.",
      "De retour à Babylone, planifiant une expédition en Arabie, Alexandre tomba dans une fièvre soudaine après une nuit de forte beuverie. Le 11 juin 323 av. J.-C., il mourut dans le palais de Nabuchodonosor, à un mois de ses trente-trois ans. À qui laissait-il l'empire, lui demanda-t-on sur son lit de mort ? Il aurait murmuré « au plus fort ». Ses généraux — les diadoques — s'exécutèrent, déchirant l'empire en quarante ans de guerre : Ptolémée prit l'Égypte, Séleucos prit l'Asie, les héritiers d'Antigone prirent la Macédoine même.\n\nPourtant la conquête survécut au conquérant. Le grec devint la langue commune de l'Adriatique à l'Afghanistan ; cités, théâtres et gymnases grecs surgirent sur trois continents ; la Bibliothèque et le Musée d'Alexandrie firent de l'Égypte la capitale intellectuelle du monde. Cette civilisation hellénistique — culture grecque fondue aux traditions perse, égyptienne et indienne — façonna le monde dont Rome hériterait, le monde dans lequel serait écrit le Nouveau Testament. Le garçon de Pella n'avait pas seulement conquis le monde antique ; il l'avait recâblé.",
    ],
  },
  'ancient-08': {
    de: [
      "Als Alexander der Große 323 v. Chr. ohne klaren Erben in Babylon starb, beantworteten seine Feldherren die Frage „Wem gehört das Reich?“ mit vierzig Jahren Krieg. Diese Diadochen — „Nachfolger“ — teilten die Eroberungen immer wieder neu auf, bis sich drei große Dynastien festigten: die Ptolemäer in Ägypten, die Seleukiden im alten persischen Kernland und die Antigoniden in Makedonien und Griechenland.\n\nObwohl Alexanders Reich als Staat nicht überdauerte, überlebte es als Welt. Griechisch wurde die gemeinsame Sprache (Koine) von Verwaltung und Handel von der Adria bis nach Afghanistan, und Städte griechischen Stils mit Theatern, Gymnasien und Agoren sprossen Tausende Kilometer von Athen entfernt.",
      "Keine Stadt verkörperte das Zeitalter wie Alexandria, von Alexander an Ägyptens Küste gegründet und von Ptolemaios I. zur Hauptstadt gemacht. Sein Doppelhafen bewältigte das Getreide des Niltals; sein Pharos-Leuchtturm, eines der Sieben Weltwunder, wies den Schiffen von einem über 100 Meter hohen Turm den Weg.\n\nDie Ptolemäer steckten königlichen Reichtum in das Museion — eine Forschungsstätte, deren Gelehrte von der Krone besoldet wurden — und in seine berühmte Bibliothek, die eine Abschrift jedes existierenden Buches suchte. In Alexandria anlegende Schiffe wurden nach Schriftrollen zum Kopieren durchsucht. Hier ordnete Euklid die Geometrie, Herophilos begründete die Anatomie und Dichter bearbeiteten die maßgeblichen Homer-Texte.",
      "Die hellenistische Wissenschaft erreichte Höhen, die Europa 1.500 Jahre nicht wiedersehen würde. Archimedes von Syrakus berechnete Pi, entdeckte das Auftriebsgesetz in seiner Wanne („Heureka!“) und baute Kriegsmaschinen, die eine römische Flotte in Schrecken versetzten. Eratosthenes, Oberbibliothekar in Alexandria, maß den Erdumfang mithilfe von Schatten in zwei Städten und einfacher Geometrie — und kam erstaunlich nahe heran.\n\nAristarch von Samos schlug siebzehn Jahrhunderte vor Kopernikus vor, dass die Erde die Sonne umkreise. Hipparch katalogisierte die Sterne und entdeckte die Präzession der Tagundnachtgleichen. Der Mechanismus von Antikythera — ein bronzener Zahnradcomputer zur Vorhersage von Finsternissen, geborgen aus einem antiken Wrack — zeigt, wie ausgefeilt die Ingenieurskunst dieser Welt geworden war.",
      "Die hellenistische Welt war ein Labor kultureller Verschmelzung. In Ägypten wurden ptolemäische Pharaonen im alten Stil gemeißelt, während sie Griechisch sprachen; der neue Gott Serapis vereinte Osiris mit Zeus. In Baktrien und Indien prägten griechische Könige Münzen mit buddhistischen Symbolen, und griechisch-buddhistische Bildhauer gaben dem Buddha sein erstes menschliches Abbild im Faltengewand des Apollon.\n\nEines nach dem anderen fielen die Nachfolgereiche an Rom — Makedonien 168 v. Chr., der seleukidische Rest 63 v. Chr. und Ägypten mit dem Tod Kleopatras VII. 30 v. Chr. Doch Rom eroberte eine bereits griechische Welt, und durch Rom wurden hellenistische Philosophie, Wissenschaft und Kunst zum Fundament der westlichen — und weiten Teilen der islamischen — Zivilisation.",
      "Nicht jede hellenistische Macht war ein Riese. Die attalidischen Könige von Pergamon in Westanatolien machten aus einer Hügelfestung und einem Schatz einen der glänzendsten Höfe der Zeit. Ihre Bibliothek wuchs so ernsthaft zur Rivalin Alexandrias heran, dass die Ptolemäer angeblich die Papyrusausfuhr sperrten und Pergamon zwangen, einen Schreibträger aus behandelter Tierhaut zu vervollkommnen: charta pergamena, das Pergament, das Medium, auf dem das mittelalterliche Europa seine Bücher abschreiben sollte. Der Große Altar von Pergamon mit seinem sich windenden Fries kämpfender Götter und Giganten bleibt eine der höchsten Leistungen der antiken Kunst. Als der letzte Attalide 133 v. Chr. starb, vermachte er sein ganzes Königreich Rom — das seltsamste Vermächtnis der antiken Geschichte und ein Zeichen dafür, wo die Macht nun lag.",
    ],
    fr: [
      "Quand Alexandre le Grand mourut à Babylone en 323 av. J.-C. sans héritier clair, ses maréchaux répondirent à la question « à qui revient l'empire ? » par quarante ans de guerre. Ces diadoques — « successeurs » — partagèrent les conquêtes encore et encore jusqu'à ce que trois grandes dynasties se stabilisent : les Ptolémées en Égypte, les Séleucides sur l'ancien cœur perse et les Antigonides en Macédoine et en Grèce.\n\nBien que l'empire d'Alexandre n'ait pas survécu comme État, il survécut comme monde. Le grec devint la langue commune (koinè) de l'administration et du commerce, de l'Adriatique à l'Afghanistan, et des cités de style grec, avec théâtres, gymnases et agoras, surgirent à des milliers de kilomètres d'Athènes.",
      "Aucune cité n'incarna l'époque comme Alexandrie, fondée par Alexandre sur la côte d'Égypte et faite capitale par Ptolémée Ier. Son double port traitait le grain de la vallée du Nil ; son phare de Pharos, l'une des Sept Merveilles, guidait les navires depuis une tour de plus de 100 mètres.\n\nLes Ptolémées versèrent la richesse royale dans le Mouseion — institution de recherche dont les savants étaient salariés par la couronne — et dans sa célèbre bibliothèque, qui cherchait une copie de chaque livre existant. Les navires accostant à Alexandrie étaient fouillés pour des rouleaux à copier. Là, Euclide organisa la géométrie, Hérophile fonda l'anatomie et des poètes établirent les textes définitifs d'Homère.",
      "La science hellénistique atteignit des sommets que l'Europe ne reverrait pas avant 1 500 ans. Archimède de Syracuse calcula pi, découvrit la loi de la poussée dans son bain (« Eurêka ! ») et construisit des machines de guerre qui terrorisèrent une flotte romaine. Ératosthène, bibliothécaire en chef d'Alexandrie, mesura la circonférence de la Terre à l'aide d'ombres dans deux villes et d'une géométrie simple — et s'en approcha étonnamment.\n\nAristarque de Samos proposa que la Terre tourne autour du Soleil dix-sept siècles avant Copernic. Hipparque catalogua les étoiles et découvrit la précession des équinoxes. La machine d'Anticythère — calculateur de bronze à engrenages pour prédire les éclipses, retrouvé dans une épave antique — montre à quel point l'ingénierie de ce monde était devenue sophistiquée.",
      "Le monde hellénistique était un laboratoire de fusion culturelle. En Égypte, les pharaons lagides étaient sculptés dans le style ancien tout en parlant grec ; le nouveau dieu Sérapis mêlait Osiris à Zeus. En Bactriane et en Inde, des rois grecs frappaient des monnaies à symboles bouddhistes, et des sculpteurs gréco-bouddhiques donnèrent au Bouddha sa première image humaine dans les drapés d'Apollon.\n\nUn à un, les royaumes successeurs tombèrent devant Rome — la Macédoine en 168 av. J.-C., le reliquat séleucide en 63 av. J.-C. et l'Égypte à la mort de Cléopâtre VII en 30 av. J.-C. Mais Rome conquit un monde déjà grec, et c'est par Rome que la philosophie, la science et l'art hellénistiques devinrent le fondement de la civilisation occidentale — et d'une grande part de la civilisation islamique.",
      "Toute puissance hellénistique n'était pas un géant. Les rois attalides de Pergame, en Anatolie occidentale, firent d'une forteresse de colline et d'un trésor l'une des cours les plus brillantes de l'époque. Leur bibliothèque grandit au point de rivaliser avec celle d'Alexandrie — si sérieusement que les Ptolémées auraient interdit l'exportation de papyrus, forçant Pergame à perfectionner un support d'écriture en peau animale traitée : la charta pergamena, le parchemin, le médium sur lequel l'Europe médiévale copierait ses livres. Le Grand Autel de Pergame, avec sa frise tourmentée de dieux combattant des géants, reste l'un des sommets de l'art antique. Quand le dernier Attalide mourut en 133 av. J.-C., il légua tout son royaume à Rome — le plus étrange legs de l'histoire antique, et un signe de là où résidait désormais le pouvoir.",
    ],
  },
  'ancient-09': {
    de: [
      "In einer einzigen Generation (550–530 v. Chr.) verschlang Kyros II. von Persien das medische, das lydische und das neubabylonische Reich und schuf etwas Neues in der Weltgeschichte: einen Staat, der fast alle zivilisierten Länder des Nahen Ostens umfasste. Das Revolutionäre an Kyros war nicht die Eroberung, sondern die Herrschaft. Statt Völker zu deportieren und Tempel nach assyrischer Art zu zerschlagen, bestätigte er örtliche Priesterschaften, achtete örtliche Bräuche und ließ die jüdischen Verbannten in Babylon heimkehren, um den Tempel Jerusalems wieder aufzubauen.\n\nDer Kyros-Zylinder, eine tönerne Proklamation seiner Herrschaft in Babylon, wird oft als frühe Charta der Toleranz beschrieben. Das von ihm gegründete Reich sollte nach diesem Grundsatz regiert werden: Vielfalt unter einem einzigen König der Könige.",
      "Dareios I. (reg. 522–486 v. Chr.) machte aus Eroberungen ein System. Er teilte das Reich in etwa zwanzig Satrapien, jede unter einem Statthalter (Satrapen), der festen Tribut einzog — Gold aus Indien, Pferde aus Kilikien, Getreide aus Ägypten. Königliche Inspektoren, „die Augen und Ohren des Königs“, bereisten die Provinzen, um Ehrgeiz und Korruption im Zaum zu halten.\n\nDareios vereinheitlichte die Goldmünze (den Dareikos), grub einen Kanal vom Nil zum Roten Meer und baute die Königsstraße von Sardes nach Susa, auf der berittene Kuriere Nachrichten in etwa einer Woche weitergaben — eine Reise, die gewöhnliche Reisende drei Monate kostete. Herodots bewundernde Beschreibung dieser Kuriere — „weder Schnee noch Regen noch Hitze noch nächtliches Dunkel“ — dient noch heute als Postmotto.",
      "Auf einer großen steinernen Terrasse im persischen Kernland begann Dareios Persepolis — eine zeremonielle Hauptstadt aus Audienzhallen, deren Säulen zwanzig Meter emporragten, gekrönt von Doppelstier-Kapitellen. Ihre Treppen tragen gemeißelte Prozessionen der Völker des Reiches: Babylonier mit Textilien, Lyder mit Vasen, Äthiopier mit Elfenbein — jeder in Landestracht, mit Tribut zum Neujahrsfest. Nirgends ist die Reichsidee der Einheit-in-Vielfalt klarer gemeißelt.\n\nDie persische Religion folgte dem Propheten Zoroaster, dessen Lehre das Dasein als sittlichen Kampf zwischen Wahrheit (Asha) und Lüge (Druj) unter dem weisen Herrn Ahura Mazda begriff. Zoroastrische Vorstellungen — ein kosmischer Kampf von Gut und Böse, ein Gericht nach dem Tod, eine endgültige Erneuerung der Welt — sollten in Judentum, Christentum und Islam nachhallen.",
      "Die Westausdehnung des Reiches verstrickte es mit den zänkischen griechischen Stadtstaaten. Die großen Invasionen von 490 und 480 v. Chr. — Marathon, Thermopylen, Salamis — scheiterten und verankerten „die Perserkriege“ im griechischen Gedächtnis als Triumph freier Bürger über die Untertanen eines Königs. Die Wirklichkeit war feiner: Persien blieb weitere 150 Jahre die beherrschende Macht des östlichen Mittelmeers, finanzierte und schlichtete griechische Streitigkeiten.\n\nDas Ende kam aus dem Nordwesten. Zwischen 334 und 330 v. Chr. zerschlug Alexander von Makedonien die Heere Dareios' III. bei Granikos, Issos und Gaugamela und brannte Persepolis nieder. Doch der Eroberer regierte wie die Achämeniden — durch Satrapien, Tribut und Toleranz —, ein Beweis, dass Persien die Vorlage des Imperiums erfunden hatte, die alle nach ihm kopieren würden.",
      "Der Kern des achämenidischen Heeres war das Elitekorps, das die Griechen die Zehntausend Unsterblichen nannten — so genannt, weil seine Stärke stets bei genau 10.000 gehalten wurde, jeder Gefallene sofort ersetzt. Hinter ihnen marschierte eine wahrhaft imperiale Streitmacht: medische Reiterei, babylonische Bogenschützen, baktrische Kamelreiter, ägyptische Seesoldaten — jedes Kontingent in Landestracht unter eigenen Offizieren, das ganze Heer ein Abbild des Reiches selbst. Persiens wahres militärisches Genie aber war die Infrastruktur: Königsstraßen, die Heere in Wochen verschoben, Nachschublager, die Hunderttausende speisten, und eine Flotte aus phönizischen und griechischen Untertanengeschwadern. Persien zog gewöhnlich Gold den Pfeilen vor — es finanzierte eine griechische Stadt gegen die andere, bis, wie ein spartanischer König klagte, ihn „zehntausend persische Bogenschützen“ aus Asien vertrieben: der auf jedem goldenen Dareikos geprägte Bogenschütze.",
    ],
    fr: [
      "En une seule génération (550–530 av. J.-C.), Cyrus II de Perse engloutit les empires mède, lydien et néo-babylonien pour créer quelque chose de nouveau dans l'histoire du monde : un État couvrant presque toutes les terres civilisées du Proche-Orient. Ce qui rendait Cyrus révolutionnaire n'était pas la conquête mais le gouvernement. Au lieu de déporter les peuples et de fracasser les temples à la manière assyrienne, il confirma les clergés locaux, respecta les coutumes locales et laissa les exilés juifs de Babylone rentrer reconstruire le temple de Jérusalem.\n\nLe cylindre de Cyrus, proclamation d'argile de son règne à Babylone, est souvent décrit comme une charte précoce de tolérance. L'empire qu'il fonda serait gouverné selon ce principe : la diversité sous un seul roi des rois.",
      "Darius Ier (r. 522–486 av. J.-C.) fit des conquêtes un système. Il divisa l'empire en une vingtaine de satrapies, chacune sous un gouverneur (satrape) qui percevait un tribut fixe — or de l'Inde, chevaux de Cilicie, grain d'Égypte. Des inspecteurs royaux, « les yeux et les oreilles du roi », parcouraient les provinces pour brider l'ambition et la corruption.\n\nDarius standardisa la monnaie d'or (le darique), creusa un canal du Nil à la mer Rouge et bâtit la Route royale de Sardes à Suse, sur laquelle des courriers montés relayaient les messages en une semaine environ — trajet que les voyageurs ordinaires mettaient trois mois à parcourir. La description admirative d'Hérodote de ces courriers — « ni la neige, ni la pluie, ni la chaleur, ni l'obscurité de la nuit » — sert encore de devise postale aujourd'hui.",
      "Sur une grande terrasse de pierre au cœur de la Perse, Darius entreprit Persépolis — capitale cérémonielle de salles d'audience dont les colonnes s'élevaient à vingt mètres, couronnées de chapiteaux à double taureau. Ses escaliers portent des processions sculptées des peuples de l'empire : Babyloniens avec des tissus, Lydiens avec des vases, Éthiopiens avec de l'ivoire — chacun en costume national, apportant le tribut à la fête du Nouvel An. Nulle part l'idée impériale d'unité dans la diversité n'est gravée plus clairement.\n\nLa religion perse suivait le prophète Zoroastre, dont l'enseignement voyait l'existence comme une lutte morale entre la vérité (asha) et le mensonge (druj) sous le sage seigneur Ahura Mazda. Les idées zoroastriennes — une bataille cosmique du bien et du mal, un jugement après la mort, un renouvellement final du monde — résonneraient dans le judaïsme, le christianisme et l'islam.",
      "La portée occidentale de l'empire l'empêtra avec les turbulentes cités-États grecques. Les grandes invasions de 490 et 480 av. J.-C. — Marathon, les Thermopyles, Salamine — échouèrent, fixant « les guerres médiques » dans la mémoire grecque comme le triomphe de citoyens libres sur les sujets d'un roi. La réalité était plus subtile : la Perse resta la puissance dominante de la Méditerranée orientale pendant encore 150 ans, finançant et arbitrant les querelles grecques.\n\nLa fin vint du nord-ouest. Entre 334 et 330 av. J.-C., Alexandre de Macédoine fracassa les armées de Darius III au Granique, à Issos et à Gaugamèles, et incendia Persépolis. Pourtant le conquérant gouverna comme les Achéménides — par satrapies, tribut et tolérance — preuve que la Perse avait inventé le modèle d'empire que tous copieraient après elle.",
      "Le cœur de l'armée achéménide était le corps d'élite que les Grecs appelaient les Dix Mille Immortels — ainsi nommés parce que leur effectif était toujours maintenu à exactement 10 000, chaque homme tombé aussitôt remplacé. Derrière eux marchait une force véritablement impériale : cavalerie mède, archers babyloniens, cavaliers de chameaux bactriens, fantassins de marine égyptiens — chaque contingent en costume national sous ses propres officiers, l'armée entière un portrait de l'empire lui-même. Mais le vrai génie militaire de la Perse était l'infrastructure : routes royales déplaçant les armées en semaines, dépôts nourrissant des centaines de milliers d'hommes, et une flotte de escadres sujettes phéniciennes et grecques. La Perse préférait d'ordinaire l'or aux flèches — finançant une cité grecque contre une autre jusqu'à ce que, comme s'en plaignit un roi spartiate, il fût chassé d'Asie par « dix mille archers perses » : l'archer frappé sur chaque darique d'or.",
    ],
  },
  'medieval-01': {
    de: [
      "Im 5. Jahrhundert n. Chr. zerbröckelte das Weströmische Reich unter dem Druck germanischer Stämme, wirtschaftlichem Zusammenbruch und politischer Instabilität. 410 n. Chr. plünderten die Westgoten Rom — ein Ereignis, das die antike Welt erschütterte. 476 n. Chr. setzte der germanische Heerführer Odoaker den letzten weströmischen Kaiser ab, das herkömmliche Ende Roms.\n\nGermanische Königreiche — Franken, Westgoten, Ostgoten — ersetzten die römischen Provinzen. Die katholische Kirche wahrte die Kontinuität, bewahrte die lateinische Schriftkultur und leistete soziale Dienste im ganzen ehemaligen Reich.",
      "Der Frankenkönig Karl der Große (reg. 768–814 n. Chr.) einte durch Eroberung weite Teile Westeuropas. Am Weihnachtstag 800 krönte Papst Leo III. ihn zum „Kaiser der Römer“. Karl förderte die Bildung, vereinheitlichte Maße und Gewichte und holte Gelehrte an seinen Hof in Aachen.\n\nDie karolingische Renaissance half, klassische Texte zu bewahren. Nach Karls Tod wurde sein Reich unter seinen Enkeln im Vertrag von Verdun (843) geteilt und schuf die groben Umrisse des heutigen Frankreich und Deutschland.",
      "Die mittelalterliche europäische Gesellschaft ordnete sich um den Feudalismus — ein hierarchisches System aus Grundbesitz und Kriegsdienstpflicht. Könige verliehen Adligen Land gegen Kriegsdienst. Adlige gaben es an Ritter weiter; Bauern (Leibeigene) bearbeiteten das Land gegen Schutz. Das Herrengut — ein selbstversorgender Betrieb — war die wirtschaftliche Grundeinheit.\n\nDie katholische Kirche stand abseits — und oft über — dieser weltlichen Hierarchie. Klöster bewahrten Handschriften, führten Schulen und betrieben Hospitäler. Diese Verflechtung von geistlicher und weltlicher Macht prägte die mittelalterliche europäische Zivilisation.",
      "Während Westrom zerfiel, überdauerte das Oströmische Reich — das Byzantinische Reich — weitere tausend Jahre, ehe es 1453 den osmanischen Türken fiel. Konstantinopel (das heutige Istanbul), 330 n. Chr. von Kaiser Konstantin am Bosporus erbaut, war jahrhundertelang Europas größte und reichste Stadt. Unter Kaiser Justinian I. (reg. 527–565 n. Chr.) eroberte Byzanz weite Teile des früheren Westreichs zurück und schuf die Hagia Sophia — seine prächtige Kuppelkirche — sowie das Corpus Juris Civilis, eine systematische Kodifizierung des römischen Rechts.\n\nByzanz war eine entscheidende kulturelle Brücke. Griechische und römische Klassiker blieben in byzantinischen Bibliotheken erhalten, als die westliche Bildung stark zurückgegangen war. Byzantinische Gelehrte, die im 15. Jahrhundert dem osmanischen Vormarsch entflohen, brachten Handschriften nach Italien und trugen so zum Auslösen der Renaissance bei. Die byzantinische Kunst — ikonische Mosaiken aus Gold und satter Farbe — prägte eine Tradition, die sich über Osteuropa und Russland verbreitete, wo das orthodoxe Christentum tiefe Wurzeln schlug.",
      "Zwischen etwa 793 und 1100 n. Chr. entfesselten die Nordvölker Skandinaviens eine dramatische Expansion über Europa hinaus. Ihre Langschiffe — flachgehende, hochseetüchtige Boote, die offene See wie Flüsse befahren konnten — verliehen ihnen beispiellose Beweglichkeit. Der Überfall von 793 auf das Kloster Lindisfarne kündigte einem entsetzten Europa die Wikingerzeit an.\n\nDoch die Wikinger waren mehr als Räuber. Nordische Händler erschlossen Routen von der Ostsee bis nach Konstantinopel und Bagdad. Schwedisch-nordische (warägische) Krieger gründeten den Rus-Staat — Vorfahr Russlands und der Ukraine — um Nowgorod und Kiew. Norwegische Wikinger besiedelten Island, Grönland, und um 1000 n. Chr. erreichte Leif Eriksson Nordamerika — fünf Jahrhunderte vor Kolumbus. Nordische Siedler in Nordfrankreich wurden zu den Normannen, die 1066 England eroberten und dessen Kultur, Sprache und Herrschaft verwandelten.",
    ],
    fr: [
      "Au Ve siècle, l'Empire romain d'Occident s'effritait sous la pression des tribus germaniques, de l'effondrement économique et de l'instabilité politique. En 410, les Wisigoths pillèrent Rome — événement qui choqua le monde antique. En 476, le chef germanique Odoacre déposa le dernier empereur d'Occident, marquant la fin traditionnelle de Rome.\n\nDes royaumes germaniques — Francs, Wisigoths, Ostrogoths — remplacèrent les provinces romaines. L'Église catholique maintint la continuité, préservant la culture écrite latine et assurant des services sociaux à travers l'ancien empire.",
      "Le roi franc Charlemagne (r. 768–814) réunifia une grande partie de l'Europe occidentale par la conquête. Le jour de Noël 800, le pape Léon III le couronna « empereur des Romains ». Charlemagne encouragea l'éducation, uniformisa poids et mesures et attira des savants à sa cour d'Aix-la-Chapelle.\n\nLa renaissance carolingienne aida à préserver les textes classiques. À la mort de Charlemagne, son empire fut partagé entre ses petits-fils par le traité de Verdun (843), esquissant les contours de la France et de l'Allemagne modernes.",
      "La société médiévale européenne s'organisa autour de la féodalité — un système hiérarchique de propriété foncière et d'obligation militaire. Les rois octroyaient des terres aux nobles en échange du service militaire. Les nobles les sous-inféodaient aux chevaliers ; les paysans (serfs) travaillaient la terre en échange de protection. Le manoir — un domaine autosuffisant — était l'unité économique de base.\n\nL'Église catholique se tenait à l'écart — et souvent au-dessus — de cette hiérarchie séculière. Les monastères préservaient les manuscrits, tenaient des écoles et fournissaient des hôpitaux. Cet entrelacement du pouvoir religieux et séculier définit la civilisation médiévale européenne.",
      "Tandis que Rome d'Occident s'effondrait, l'Empire romain d'Orient — l'Empire byzantin — survécut mille ans de plus, tombant enfin devant les Turcs ottomans en 1453. Constantinople (l'actuelle Istanbul), bâtie par l'empereur Constantin en 330 sur le Bosphore, fut des siècles durant la plus grande et la plus riche ville d'Europe. Sous l'empereur Justinien Ier (r. 527–565), Byzance reconquit une grande part de l'ancien Empire d'Occident et produisit Sainte-Sophie — sa magnifique église à coupole — et le Corpus Juris Civilis, codification systématique du droit romain.\n\nByzance servit de pont culturel décisif. Les classiques grecs et romains furent préservés dans les bibliothèques byzantines quand la culture écrite occidentale avait fortement décliné. Des savants byzantins fuyant l'avancée ottomane au XVe siècle apportèrent des manuscrits en Italie, contribuant à déclencher la Renaissance. L'art byzantin — mosaïques emblématiques d'or et de couleurs riches — définit une tradition qui se répandit à travers l'Europe de l'Est et la Russie, où le christianisme orthodoxe s'enracina profondément.",
      "Entre 793 et 1100 environ, les peuples nordiques de Scandinavie lancèrent une expansion spectaculaire à travers l'Europe et au-delà. Leurs langskips — vaisseaux à faible tirant d'eau, dignes de l'océan, capables de naviguer en haute mer comme sur les rivières — leur donnaient une mobilité sans égale. Le raid de 793 sur le monastère de Lindisfarne annonça l'âge viking à une Europe horrifiée.\n\nMais les Vikings étaient plus que des pillards. Des marchands nordiques établirent des routes de la Baltique à Constantinople et Bagdad. Des guerriers suédo-nordiques (varègues) fondèrent l'État de la Rus — ancêtre de la Russie et de l'Ukraine — autour de Novgorod et de Kiev. Des Vikings norvégiens colonisèrent l'Islande, le Groenland, et vers l'an 1000, Leif Erikson atteignit l'Amérique du Nord — cinq siècles avant Colomb. Les colons nordiques du nord de la France devinrent les Normands, qui conquirent l'Angleterre en 1066 et en transformèrent la culture, la langue et le gouvernement.",
    ],
  },
  'medieval-02': {
    de: [
      "610 n. Chr. empfing der Kaufmann Mohammed in einer Höhle bei Mekka seine erste Offenbarung und begründete die Religion des Islam. Bei seinem Tod 632 n. Chr. war der Großteil Arabiens unter dem Islam geeint. Binnen eines Jahrhunderts hatten arabische Heere das Perserreich, Ägypten, Nordafrika und Spanien erobert — eine der raschesten imperialen Ausdehnungen der Geschichte.\n\nDie Kalifate der Umayyaden und Abbasiden schufen eine weite, kosmopolitische islamische Welt von der Atlantikküste bis nach Zentralasien. Arabisch wurde zur Sprache der Gelehrsamkeit, des Handels und der Religion und verband vielfältige Völker von Spanien bis Persien.",
      "Während Westeuropa sich langsam vom Fall Roms erholte, erlebte die islamische Welt ein Goldenes Zeitalter geistiger Leistungen (8.–13. Jahrhundert). Der Abbasidenhof in Bagdad wurde zum größten Zentrum der Gelehrsamkeit der Welt. Gelehrte übersetzten griechische Texte von Aristoteles, Euklid und Galen und bewahrten sie vor dem Verlust.\n\nIslamische Gelehrte leisteten eigenständige Beiträge in Mathematik (die Algebra entwickelte al-Chwarizmi), Astronomie, Medizin (Ibn Sinas Kanon der Medizin wurde jahrhundertelang an europäischen Universitäten verwendet) und Optik. Dieses Wissen floss später nach Europa zurück und half, die wissenschaftliche Revolution zu entzünden.",
      "1095 rief Papst Urban II. zu einem heiligen Krieg auf, um Jerusalem von den Seldschuken zurückzuerobern. Der Erste Kreuzzug gelang — Jerusalem fiel 1099 den Kreuzfahrern. Vier Kreuzfahrerstaaten entstanden im Heiligen Land. Doch die christliche Herrschaft erwies sich als brüchig; Saladin, der kurdische Sultan Ägyptens, nahm Jerusalem 1187 wieder ein.\n\nSieben große Kreuzzüge folgten über zwei Jahrhunderte. Militärisch letztlich gescheitert, prägten sie doch die europäische wie die islamische Zivilisation zutiefst. Sie verstärkten den Handel mit dem Osten, führten Europäer an islamische Gelehrsamkeit und Waren heran und hinterließen tiefe religiöse Feindschaften, die jahrhundertelang nachhallten.",
      "Saladin (1137–1193), der kurdische Feldherr, der das muslimische Ägypten und Syrien einte, wurde einer der am meisten bewunderten Herrscher der mittelalterlichen Welt — von Christen wie Muslimen. 1187 nahmen seine Truppen Jerusalem zurück und behandelten die christlichen Bewohner mit einer Milde, die im scharfen Gegensatz zum Massaker bei der Einnahme der Stadt durch den Ersten Kreuzzug stand. Der Dritte Kreuzzug führte Europas größte Kriegerkönige — Richard I. von England und Philipp II. von Frankreich — ins Heilige Land.\n\nDas legendäre Duell zwischen Richard und Saladin endete mit einem Vertrag, der christlichen Pilgern Zugang zu Jerusalem gewährte. Die Kreuzzüge verdichteten den Begriff des Rittertums — ein Verhaltenskodex, der militärische Tüchtigkeit mit christlichen Idealen und höfischer Höflichkeit verband. Ritterorden wie die Templer und Johanniter verbanden klösterliche Disziplin mit kriegerischem Können und verkörperten Ideale, die die europäische Adelskultur jahrhundertelang prägten.",
      "Die Kreuzzüge verstärkten den Handel zwischen Europa und der islamischen Welt dramatisch. Italienische Stadtstaaten — Venedig, Genua, Pisa — stellten Transport für Kreuzfahrer gegen Handelsrechte in östlichen Häfen. Venezianische Kaufleute führten Gewürze, Seide, Glas und Luxusgüter ein, die Italien bereicherten und die europäische Konsumkultur verwandelten.\n\nDieser Reichtum befeuerte eine städtische Handelsrevolution. Norditalienische Städte entwickelten ausgefeilte Finanzinstrumente: Kreditbriefe, doppelte Buchführung, Seeversicherung und frühes Bankwesen. Die Medici in Florenz waren Bankiers für Päpste und Könige. Diese kaufmännische Raffinesse schuf das Kapital und die unternehmerische Kultur, die die Renaissance finanzieren sollten — ein Beweis, dass das mittelalterliche Europa weit dynamischer war, als die Klischees vom „dunklen Zeitalter“ vermuten lassen.",
    ],
    fr: [
      "En 610, le marchand Mahomet reçut sa première révélation dans une grotte près de La Mecque, fondant la religion de l'islam. À sa mort en 632, l'essentiel de l'Arabie était unifié sous l'islam. En un siècle, les armées arabes avaient conquis l'Empire perse, l'Égypte, l'Afrique du Nord et l'Espagne — l'une des expansions impériales les plus rapides de l'histoire.\n\nLes califats omeyyade et abbasside créèrent un vaste monde islamique cosmopolite, de l'Atlantique à l'Asie centrale. L'arabe devint la langue du savoir, du commerce et de la religion, liant des peuples divers de l'Espagne à la Perse.",
      "Tandis que l'Europe occidentale se remettait lentement de la chute de Rome, le monde islamique connut un âge d'or de réalisations intellectuelles (VIIIe–XIIIe siècles). La cour abbasside de Bagdad devint le plus grand centre de savoir du monde. Des savants traduisirent les textes grecs d'Aristote, d'Euclide et de Galien, les sauvant de la perte.\n\nLes savants islamiques firent des contributions originales en mathématiques (l'algèbre fut développée par al-Khwarizmi), en astronomie, en médecine (le Canon de la médecine d'Ibn Sina fut utilisé des siècles dans les universités européennes) et en optique. Ce savoir reflua plus tard vers l'Europe, aidant à allumer la révolution scientifique.",
      "En 1095, le pape Urbain II appela à une guerre sainte pour reprendre Jérusalem aux Turcs seldjoukides. La première croisade réussit — Jérusalem tomba aux mains des croisés en 1099. Quatre États latins furent établis en Terre sainte. Mais le contrôle chrétien se révéla fragile ; Saladin, le sultan kurde d'Égypte, reprit Jérusalem en 1187.\n\nSept grandes croisades suivirent sur deux siècles. Bien qu'échouant militairement, elles façonnèrent profondément les civilisations européenne et islamique. Elles intensifièrent le commerce avec l'Orient, initièrent les Européens au savoir et aux produits islamiques, et laissèrent de profondes haines religieuses qui résonnèrent des siècles durant.",
      "Saladin (1137–1193), le général kurde qui unifia l'Égypte et la Syrie musulmanes, devint l'un des souverains les plus admirés du monde médiéval — par les chrétiens comme par les musulmans. En 1187, ses forces reprirent Jérusalem, traitant les habitants chrétiens avec une clémence qui contrastait nettement avec le massacre ayant accompagné la prise de la ville lors de la première croisade. La troisième croisade amena en Terre sainte les plus grands rois-guerriers d'Europe — Richard Ier d'Angleterre et Philippe II de France.\n\nLe duel légendaire de Richard et Saladin s'acheva par un traité autorisant l'accès des pèlerins chrétiens à Jérusalem. Les croisades cristallisèrent le concept de chevalerie — un code de conduite alliant prouesse militaire, idéaux chrétiens et courtoisie de cour. Des ordres militaires comme les Templiers et les Hospitaliers mêlaient discipline monastique et expertise martiale, incarnant des idéaux qui façonnèrent la culture aristocratique européenne pour des siècles.",
      "Les croisades intensifièrent spectaculairement le commerce entre l'Europe et le monde islamique. Des cités italiennes — Venise, Gênes, Pise — assuraient le transport des croisés en échange de droits commerciaux dans les ports orientaux. Les marchands vénitiens importaient épices, soie, verre et produits de luxe qui enrichirent l'Italie et transformèrent la culture de consommation européenne.\n\nCette richesse alimenta une révolution commerciale urbaine. Les villes du nord de l'Italie développèrent des instruments financiers sophistiqués : lettres de crédit, comptabilité en partie double, assurance maritime et banque naissante. Les Médicis de Florence étaient banquiers des papes et des rois. Cette sophistication commerciale créa le capital et la culture entrepreneuriale qui financeraient la Renaissance — montrant que l'Europe médiévale était bien plus dynamique que ne le suggèrent les clichés d'« âge sombre ».",
    ],
  },
  'medieval-03': {
    de: [
      "Der Schwarze Tod — verursacht durch das Bakterium Yersinia pestis, übertragen von Flöhen auf Ratten — entstand um 1340 in Zentralasien. Entlang der Handelswege verbreitet, erreichte er 1346 die Schwarzmeerhäfen und gelangte im Oktober 1347 über Sizilien nach Europa. Binnen fünf Jahren war er von Portugal bis Polen gefegt.\n\nDie Seuche trat in drei Formen auf: Beulenpest (geschwollene Lymphknoten), Lungenpest (Lungeninfektion) und Pestsepsis (Blutinfektion). Die zeitgenössische Medizin war machtlos. Städte traf es am härtesten — London verlor womöglich die Hälfte seiner Bevölkerung; Florenz verlor 60 %.",
      "Auf ihrem Höhepunkt tötete der Schwarze Tod täglich Tausende in den großen Städten. Die Leichen häuften sich schneller, als sie bestattet werden konnten. Die soziale Ordnung brach zusammen; Priester verweigerten die Sterbesakramente, Ärzte flohen. Manche wandten sich Geißlerbewegungen zu — öffentlich geißelten sie sich zur Buße. Paranoide Gemeinschaften massakrierten jüdische Bevölkerungen und beschuldigten sie fälschlich, Brunnen vergiftet zu haben.\n\nAls die schlimmsten Wellen in den 1350er Jahren vorübergezogen waren, hatte Europa zwischen einem Drittel und der Hälfte seiner Bevölkerung verloren. Das seelische Trauma war ungeheuer. Kunst und Literatur waren durchtränkt von Todesbildern; der „Totentanz“ (danse macabre) wurde zu einem beliebten Motiv, das eine von der Willkür der Sterblichkeit zutiefst erschütterte Gesellschaft spiegelte.",
      "Die Folgen der Pest verwandelten die europäische Gesellschaft. Da so viele Bauern gestorben waren, konnten die Überlebenden höhere Löhne und bessere Bedingungen fordern. Die Leibeigenschaft ging in Westeuropa rasch zurück. Der englische Bauernaufstand von 1381 zeigte, dass die Unterschichten ihre überlieferte Stellung nicht länger hinzunehmen bereit waren.\n\nDie Kirche, die die Katastrophe weder erklären noch aufhalten konnte, verlor an Ansehen. Das Hinterfragen kirchlicher Autorität half, den Boden für die Renaissance und später die Reformation zu bereiten. Widersinnig beschleunigte der Arbeitskräftemangel die technische Innovation — arbeitssparende Geräte wurden wirtschaftlich wertvoller, darunter die Druckerpresse.",
      "Zeitgleich mit dem Schwarzen Tod führten England und Frankreich den Hundertjährigen Krieg — eine Reihe von Konflikten um englische Ansprüche auf den französischen Thron, die 116 Jahre dauerten. Englische Langbogenschützen verwüsteten die französische Reiterei bei Crécy (1346) und Azincourt (1415), wo Heinrichs V. zahlenmäßig unterlegene Truppen ein fünfmal so großes Heer in die Flucht schlugen. Englische Verbände drangen tief nach Frankreich vor und beherrschten auf ihrem Höhepunkt weite Teile des Landes.\n\nDer Wendepunkt des Krieges kam durch Jeanne d'Arc, ein jugendliches Bauernmädchen aus Domrémy, das göttliche Visionen für sich beanspruchte, die es befahlen, Frankreichs Heer zu führen. Die französischen Truppen kehrten das Blatt; Jeanne wurde von den Engländern gefangen und 1431 auf dem Scheiterhaufen verbrannt — doch ihre Feldzüge hatten die englische Vorherrschaft gebrochen. Bis 1453 hatte England alles französische Gebiet außer Calais verloren. Der Krieg zeigte, dass die Ära der schwer gepanzerten Ritter der Infanterie und Artillerie wich.",
      "Paradoxerweise halfen die Krisen des 14. Jahrhunderts — Pest, Krieg, Papstschisma —, die Bedingungen für die kulturelle Erneuerung der Renaissance zu schaffen. Der Schwarze Tod bewirkte gewaltige Vermögensübertragungen, als Überlebende den Besitz der Toten erbten; diese Kapitalbündelung finanzierte die Förderung von Kunst und Gelehrsamkeit. Der Ansehensverlust der Kirche ermutigte zum eigenständigen Denken.\n\nFrühe Humanisten wie Petrarca (1304–1374) — oft der „erste Renaissance-Mensch“ genannt — sammelten klassische Handschriften und stellten die Menschenwürde ins Zentrum ihres Weltbilds. Boccaccios Decamerone schilderte den Schwarzen Tod und feierte zugleich Witz und menschliche Widerstandskraft. In der Kunst brach Giotto mit der byzantinischen Flächigkeit und stellte dreidimensionale, gefühlsstarke Figuren dar — eine Revolution, die dem Renaissance-Naturalismus die Tür öffnete. Die spätmittelalterliche Kultur, alles andere als bloß dunkel, war schwanger mit den kommenden Umwälzungen.",
    ],
    fr: [
      "La Peste noire — causée par la bactérie Yersinia pestis, transportée par les puces des rats — naquit en Asie centrale vers 1340. Se propageant par les routes commerciales, elle atteignit les ports de la mer Noire en 1346 et entra en Europe par la Sicile en octobre 1347. En cinq ans, elle avait balayé du Portugal à la Pologne.\n\nLa maladie prit trois formes : peste bubonique (ganglions enflés), peste pulmonaire (infection des poumons) et peste septicémique (infection du sang). La médecine de l'époque était impuissante. Les villes furent les plus touchées — Londres perdit peut-être la moitié de sa population ; Florence perdit 60 %.",
      "À son apogée, la Peste noire tuait des milliers de personnes par jour dans les grandes villes. Les corps s'entassaient plus vite qu'on ne pouvait les enterrer. L'ordre social s'effondra ; les prêtres refusaient les derniers sacrements, les médecins fuyaient. Certains se tournèrent vers les mouvements de flagellants — se fouettant publiquement en pénitence. Des communautés paranoïaques massacrèrent des populations juives, les accusant à tort d'empoisonner les puits.\n\nQuand les pires vagues passèrent dans les années 1350, l'Europe avait perdu entre un tiers et la moitié de sa population. Le traumatisme psychologique fut immense. L'art et la littérature se saturèrent d'images de mort ; la « danse macabre » devint un motif populaire reflétant une société profondément ébranlée par le caractère aléatoire de la mort.",
      "Les suites de la peste transformèrent la société européenne. Tant de paysans étant morts, les survivants pouvaient exiger des salaires plus élevés et de meilleures conditions. Le servage déclina rapidement en Europe occidentale. La révolte des paysans anglais de 1381 montra que les classes populaires n'acceptaient plus leur condition traditionnelle.\n\nL'Église, qui n'avait su ni expliquer ni arrêter la catastrophe, perdit son prestige. La remise en cause de l'autorité de l'Église aida à préparer le terrain de la Renaissance puis de la Réforme protestante. Paradoxalement, la pénurie de main-d'œuvre accéléra l'innovation technologique — les dispositifs économisant le travail gagnèrent en valeur, dont l'imprimerie.",
      "Concomitamment à la Peste noire, l'Angleterre et la France livrèrent la guerre de Cent Ans — une série de conflits sur les prétentions anglaises au trône de France, durant 116 ans. Les archers anglais dévastèrent la cavalerie française à Crécy (1346) et à Azincourt (1415), où les forces d'Henri V, en infériorité, mirent en déroute une armée cinq fois supérieure. Les armées anglaises pénétrèrent profondément en France et contrôlèrent à leur apogée une grande partie du pays.\n\nLe tournant de la guerre vint par Jeanne d'Arc, une jeune paysanne de Domrémy affirmant des visions divines lui ordonnant de mener l'armée de France. Les forces françaises renversèrent la vapeur ; Jeanne fut capturée par les Anglais et brûlée vive en 1431 — mais ses campagnes avaient brisé la domination anglaise. En 1453, l'Angleterre avait perdu tout territoire français hormis Calais. La guerre montra que l'ère des chevaliers lourdement cuirassés cédait la place à l'infanterie et à l'artillerie.",
      "Paradoxalement, les crises du XIVe siècle — peste, guerre, schisme pontifical — aidèrent à produire les conditions du renouveau culturel de la Renaissance. La Peste noire provoqua d'énormes transferts de richesse quand les survivants héritèrent des biens des morts ; cette concentration de capital finança le mécénat des arts et du savoir. La perte de prestige de l'Église encouragea la pensée indépendante.\n\nDes humanistes précoces comme Pétrarque (1304–1374) — souvent appelé le « premier homme de la Renaissance » — collectionnaient les manuscrits classiques et plaçaient la dignité humaine au centre de leur vision du monde. Le Décaméron de Boccace dépeignait la Peste noire tout en célébrant l'esprit et la résilience humaine. En art, Giotto rompit avec la platitude byzantine pour représenter des figures tridimensionnelles et expressives — une révolution qui ouvrit la porte au naturalisme de la Renaissance. La culture de la fin du Moyen Âge, loin d'être simplement sombre, était grosse des transformations à venir.",
    ],
  },
  'medieval-04': {
    de: [
      "Das Frühmittelalter (ca. 500–1000 n. Chr.) erlebte nach dem Fall Roms einen dramatischen Rückgang des europäischen Handels. Lokale Herren wurden auf ihren Gütern selbstversorgend; der Fernhandel verschwand fast völlig. Doch ab etwa 1000 n. Chr. besserten sich die Verhältnisse: Das Klima erwärmte sich leicht (die mittelalterliche Warmzeit), die Bevölkerung wuchs, und landwirtschaftliche Überschüsse schufen Nachfrage nach Gütern über das Existenzminimum hinaus.\n\nKaufleute begannen, regelmäßige Rundreisen zwischen wachsenden Städten zu unternehmen. Wochenmärkte und Jahrmessen vervielfachten sich. Die großen Champagne-Messen im Nordosten Frankreichs wurden zum Handelsdrehkreuz Europas und zogen Händler aus Italien, Flandern, Deutschland und der Levante an. Hier wechselten Seide und Gewürze aus dem Osten den Besitzer gegen flämische Wolle, venezianisches Glas und deutsche Metallarbeit. Eine Handelsrevolution war im Gange.",
      "Um diese Handelsausweitung zu regeln, schlossen sich Handwerker und Kaufleute zu Zünften zusammen — Verbände, die den Zugang zu den Gewerben kontrollierten, Qualitätsnormen setzten und die nächste Generation ausbildeten. Zünfte umfassten alles von Bäckern und Metzgern bis zu Goldschmieden und Wundärzten. Meister zu werden erforderte Jahre: zuerst als Lehrling (im Haushalt des Meisters lebend), dann als Geselle (bezahlter Tagelöhner) und schließlich mit einer Meisterprüfung, um als Vollmitglied in die Zunft einzutreten.\n\nZünfte schützten ihre Mitglieder vor auswärtiger Konkurrenz, legten Lehrzeiten fest, setzten Löhne und erzwangen Qualitätsnormen — Prüfer konnten minderwertige Waren beschlagnahmen oder vernichten. Doch sie erfüllten auch soziale Aufgaben: Sie unterstützten kranke Mitglieder, förderten religiöse Feiern, organisierten aufwendige Festzüge und Mysterienspiele. Das Zunftwesen prägte das städtische Wirtschaftsleben vom 12. Jahrhundert an, bis die industrielle Revolution es überflüssig machte.",
      "In Nordeuropa bildeten deutsche Kaufmannsstädte die Hanse — ein Handelsbündnis, das schließlich über 200 Städte von London bis Nowgorod umfasste und über zwei Jahrhunderte den Ostsee- und Nordseehandel beherrschte. Lübeck war die informelle Hauptstadt des Bundes; Hamburg, Bremen, Danzig und Riga waren Schlüsselmitglieder.\n\nHansekaufleute entwickelten ausgefeilte Handelspraktiken: einheitliche Maße und Gewichte, Handelsverträge, Frachtversicherung und Kaufmannsgerichte zur Streitbeilegung. Hanse-Handelsniederlassungen (Kontore) in London, Brügge, Bergen und Nowgorod waren regelrechte Städte in der Stadt, mit eigenen Lagerhäusern, Kirchen und Rechtsprivilegien. Der Erfolg der Hanse zeigte, dass mittelalterliche Menschen zu außerordentlicher kaufmännischer Raffinesse fähig waren — die Wurzeln des modernen Kapitalismus reichten tief in die mittelalterliche Stadt.",
      "Die Beulenpest gelangte 1347 aus Zentralasien nach Europa, getragen von Flöhen auf Ratten an Bord genuesischer Handelsschiffe. Binnen vier Jahren tötete sie zwischen 30 und 60 Prozent der Bevölkerung Europas — vielleicht 25 Millionen Menschen. Ganze Dörfer verschwanden. Das englische Dorf Eyam würde sich später während der Pest von 1665 vollständig abriegeln, um deren Ausbreitung zu verhindern.\n\nDie demografische Katastrophe verwandelte die Wirtschaft. Da Arbeitskräfte plötzlich knapp waren, konnten überlebende Bauern höhere Löhne und bessere Bedingungen fordern — ein wesentlicher Faktor beim Niedergang der Leibeigenschaft. Grundherren rangen um Arbeiter; manche Bauern wurden erstmals Freibauern. Die Pest erschütterte auch die überkommene Autorität, untergrub das Vertrauen in die Schutzmacht der Kirche und beschleunigte womöglich die gesellschaftlichen Veränderungen, die in Renaissance und Reformation gipfeln sollten. Die Katastrophe half paradoxerweise, die moderne Welt zu gebären.",
      "Mittelalterliche Kaufleute brauchten ausgefeilte Finanzwerkzeuge. Die Kirche verdammte das Verleihen gegen Zins als „Wucher“, doch clevere Bankiers fanden Umwege. Italienische Kaufleute erfanden den Wechsel — eine schriftliche Anweisung, mit der Kaufleute Kredit über Städte hinweg übertragen konnten, ohne Gold physisch zu bewegen, was das Raubrisiko auf mittelalterlichen Straßen drastisch senkte.\n\nDie Medici in Florenz stiegen zur beherrschenden Finanzmacht des 15. Jahrhunderts auf. Ihr Bankennetz spannte sich über Europa und finanzierte Päpste, Könige und Kaufleute. Giovanni di Bicci de' Medici und seine Nachfahren entwickelten die doppelte Buchführung, Filialstrukturen zur Haftungsbegrenzung und ausgefeilte Kreditinstrumente. Cosimo de' Medici wurde faktischer Herrscher von Florenz — ein Beweis, dass Finanzmacht der militärischen Macht ebenbürtig sein konnte. Die Medici-Förderung von Kunst und Gelehrsamkeit machte Florenz zur Wiege der Renaissance und verband kaufmännische Neuerung unmittelbar mit kultureller Revolution.",
    ],
    fr: [
      "Le haut Moyen Âge (v. 500–1000) vit le commerce européen se contracter fortement après la chute de Rome. Les seigneurs locaux devinrent autosuffisants sur leurs manoirs ; le commerce à longue distance disparut presque. Mais à partir de l'an 1000 environ, les conditions s'améliorèrent : le climat se réchauffa légèrement (l'optimum climatique médiéval), la population crût, et les surplus agricoles créèrent une demande de biens au-delà de la subsistance.\n\nLes marchands se mirent à parcourir des circuits réguliers entre les villes en croissance. Marchés hebdomadaires et foires annuelles se multiplièrent. Les grandes foires de Champagne, dans le nord-est de la France, devinrent le carrefour commercial de l'Europe, attirant des marchands d'Italie, de Flandre, d'Allemagne et du Levant. Là, soie et épices d'Orient s'échangeaient contre laine flamande, verre vénitien et métallerie allemande. Une révolution commerciale était en marche.",
      "Pour réguler cette expansion commerciale, artisans et marchands formèrent des guildes — associations qui contrôlaient l'accès aux métiers, fixaient des normes de qualité et formaient la génération suivante. Les guildes englobaient tout, des boulangers et bouchers aux orfèvres et chirurgiens. Devenir maître exigeait des années : d'abord apprenti (vivant dans la famille du maître), puis compagnon (journalier payé), et enfin réussir un chef-d'œuvre pour rejoindre la guilde comme membre à part entière.\n\nLes guildes protégeaient leurs membres de la concurrence extérieure, fixaient l'âge d'apprentissage, réglaient les salaires et imposaient des normes de qualité — les inspecteurs pouvaient saisir ou détruire les biens défectueux. Mais elles remplissaient aussi des fonctions sociales : soutenant les membres malades, parrainant les célébrations religieuses, organisant fastes cortèges et mystères. Le système des guildes façonna la vie économique urbaine du XIIe siècle jusqu'à ce que la révolution industrielle le rende obsolète.",
      "En Europe du Nord, les villes marchandes allemandes formèrent la Hanse — une alliance commerciale qui finit par englober plus de 200 villes de Londres à Novgorod, dominant le commerce de la Baltique et de la mer du Nord pendant plus de deux siècles. Lübeck en était la capitale informelle ; Hambourg, Brême, Dantzig et Riga en étaient des membres clés.\n\nLes marchands hanséates développèrent des pratiques commerciales sophistiquées : poids et mesures standardisés, contrats commerciaux, assurance de cargaison et tribunaux marchands pour trancher les litiges. Les comptoirs hanséates (Kontore) à Londres, Bruges, Bergen et Novgorod étaient de véritables villes dans les villes, avec leurs entrepôts, églises et privilèges juridiques. Le succès de la Hanse montra que les gens du Moyen Âge étaient capables d'une extraordinaire sophistication commerciale — les racines du capitalisme moderne plongeaient profondément dans la ville médiévale.",
      "La peste bubonique arriva en Europe depuis l'Asie centrale en 1347, portée par les puces des rats à bord de navires génois. En quatre ans, elle tua entre 30 et 60 pour cent de la population européenne — peut-être 25 millions de personnes. Des villages entiers disparurent. Le village anglais d'Eyam se cloîtrerait plus tard entièrement lors de la peste de 1665 pour empêcher sa propagation.\n\nLa catastrophe démographique transforma l'économie. La main-d'œuvre devenant soudain rare, les paysans survivants purent exiger des salaires plus élevés et de meilleures conditions — facteur majeur du déclin du servage. Les seigneurs se disputaient les travailleurs ; certains paysans devinrent propriétaires pour la première fois. La peste bouleversa aussi l'autorité traditionnelle, ébranla la foi dans le pouvoir protecteur de l'Église et accéléra peut-être les changements sociaux qui culmineraient dans la Renaissance et la Réforme. La catastrophe, paradoxalement, aida à enfanter le monde moderne.",
      "Les marchands médiévaux avaient besoin d'outils financiers sophistiqués. L'Église condamnait le prêt à intérêt comme « usure », mais d'astucieux banquiers trouvèrent des contournements. Les marchands italiens inventèrent la lettre de change — un ordre écrit permettant de transférer un crédit d'une ville à l'autre sans déplacer physiquement l'or, réduisant fortement le risque de vol sur les routes médiévales.\n\nLes Médicis de Florence s'élevèrent pour dominer la finance du XVe siècle. Leur réseau bancaire s'étendait à travers l'Europe, finançant papes, rois et marchands. Giovanni di Bicci de' Medici et ses descendants développèrent la comptabilité en partie double, des structures en succursales pour limiter le risque et des instruments de crédit sophistiqués. Cosme de Médicis devint le maître effectif de Florence — montrant que la puissance financière pouvait rivaliser avec la puissance militaire. Le mécénat des Médicis pour l'art et le savoir fit de Florence le berceau de la Renaissance, liant directement l'innovation commerciale à la révolution culturelle.",
    ],
  },
  'medieval-05': {
    de: [
      "In den rauen Steppen Zentralasiens wurde um 1162 n. Chr. ein Junge namens Temüdschin in einen unbedeutenden Mongolenclan geboren. Nach Jahren der Not — sein Vater von Rivalen vergiftet, Temüdschin selbst gefangen gehalten — stieg er durch eine Mischung aus außerordentlichem militärischem Talent, politischer Schläue und rücksichtsloser Entschlossenheit auf und einte die ewig verfeindeten Mongolenstämme.\n\n1206 wurde Temüdschin bei einer großen Versammlung (Kurultai) mongolischer Häuptlinge am Fluss Onon zum Dschingis Khan — „Universalherrscher“ — ausgerufen. Er verwandelte die versammelten Stämme sogleich in eine disziplinierte Kriegsmaschine, nach Dezimalprinzipien gegliedert: Einheiten von zehn, hundert, tausend und zehntausend. Die Treue galt der Einheit und dem Khan, nicht dem Clan — ein revolutionärer Wandel, der die Stammeskriege beendete, die die Mongolen über Generationen geschwächt hatten.",
      "Mongolische Heere waren die wirksamste Streitmacht der mittelalterlichen Welt und verbanden Beweglichkeit, Disziplin, psychologische Kriegsführung und taktische Raffinesse. Berittene Bogenschützen konnten 80–100 km am Tag zurücklegen und über weite Entfernungen operieren, die Infanteriearmeen lahmgelegt hätten. Vor einer Schlacht boten mongolische Gesandte den Städten eine krasse Wahl: sich ergeben und verschont bleiben oder Widerstand leisten und der völligen Vernichtung ins Auge sehen.\n\nStädte, die sich unterwarfen, wurden im Allgemeinen mit pragmatischer Milde behandelt — ihre Handwerker, Ingenieure und Verwalter wurden in die mongolische Staatsmaschine aufgenommen. Städte, die Widerstand leisteten, wurden als Warnung an andere geschleift. Als die große Stadt Zhongdu (das heutige Peking) 1215 fiel, berichteten ausländische Reisende, die Gebeine ihrer Bewohner hätten die Ebenen kilometerweit weiß gefärbt. Diese Verbindung von Milde und Schrecken erwies sich als verheerend wirksam: Die Nachricht von mongolischen Feldzügen bewog Städte oft, sich kampflos zu ergeben.",
      "Bei Dschingis Khans Tod 1227 beherrschten die Mongolen ein Reich, das sich von der Pazifikküste Chinas bis zum Kaspischen Meer erstreckte. Seine Nachfolger stießen noch weiter vor. Ögedei Khan vollendete die Eroberung Nordchinas; Batu Khan fegte durch Russland und Polen und erreichte die Adria, ehe er sich zurückzog. Hülegü Khan plünderte 1258 Bagdad, tötete den Abbasidenkalifen und beendete fünf Jahrhunderte islamischer kultureller Vorherrschaft.\n\nAuf seinem Höhepunkt war das Mongolenreich das größte zusammenhängende Landreich der Geschichte, 24 Millionen Quadratkilometer — etwa die Größe Afrikas. Es umfasste den Großteil der eurasischen Landmasse und hielt vielleicht 100 Millionen Menschen unter seiner Herrschaft. Kein Reich davor oder danach erreichte eine so rasche territoriale Ausdehnung über so vielfältige geografische und klimatische Zonen.",
      "Paradoxerweise schuf die zerstörerischste Eroberung der Geschichte eine ihrer fruchtbarsten Perioden des Kulturaustauschs. Die Pax Mongolica („Mongolischer Frieden“), etwa 1260–1350, vereinte erstmals die Handelswege Eurasiens unter einem einzigen politischen Dach. Kaufleute, Diplomaten, Missionare und Reisende konnten von China nach Europa mit relativer Sicherheit reisen und trugen Waren, Ideen, Techniken und Krankheiten die Seidenstraße entlang.\n\nMarco Polos berühmte Reise an den Hof Kublai Khans (1271–1295) war nur wegen der mongolischen Ordnung möglich. Chinesische Papierherstellung, Schießpulver und Drucktechniken wanderten westwärts; islamische Astronomie und Medizin ostwärts. Die Mongolenhöfe warben aktiv fähige Menschen ungeachtet von Religion oder Herkunft an — christliche Priester, muslimische Astronomen, chinesische Ingenieure und persische Bürokraten dienten alle am Yuan-Hof in Peking. Dieser kosmopolitische Austausch beschleunigte die technische und kommerzielle Entwicklung, die schließlich die europäische Renaissance und das Zeitalter der Entdeckungen befeuern sollte.",
      "Die mongolischen Eroberungen töteten schätzungsweise 40 Millionen Menschen — vielleicht 10 % der Weltbevölkerung — und veränderten die demografische Landschaft Zentralasiens und des Nahen Ostens dauerhaft. Irans Bevölkerung erholte sich womöglich 700 Jahre nicht auf das vormongolische Niveau. Die Zerstörung der Bewässerungssysteme Bagdads trug zum langfristigen landwirtschaftlichen Niedergang Mesopotamiens bei. Die einst großen Städte Zentralasiens — Samarkand, Buchara, Merw — erlangten ihre vormongolische Blüte nie ganz zurück.\n\nDoch die Mongolenherrschaft schuf auch. Kublai Khans Yuan-Dynastie (1271–1368) brachte China eine gewaltige wirtschaftliche Entwicklung: Papiergeld wurde vereinheitlicht, der Kaiserkanal verlängert und das Postrelaissystem (Yam) ermöglichte Kommunikation über das Reich in bisher unerreichter Geschwindigkeit. Die mongolischen Nachfolgestaaten — das Ilchanat in Persien, die Goldene Horde in Russland, das Tschagatai-Khanat in Zentralasien — traten allmählich zum Islam über und übernahmen lokale Kulturen, was eigenständige künstlerische und architektonische Traditionen hervorbrachte. Russlands lange mongolische Unterwerfung prägte seine autokratische politische Kultur. Der mongolische Augenblick, so kurz er war, ordnete Eurasien dauerhaft neu.",
    ],
    fr: [
      "Dans les steppes rudes d'Asie centrale, un garçon nommé Temüjin naquit vers 1162 dans un clan mongol mineur. Après des années d'épreuves — son père empoisonné par des rivaux, Temüjin lui-même tenu captif — il s'éleva par un mélange de talent militaire extraordinaire, de ruse politique et de détermination impitoyable pour unir les tribus mongoles perpétuellement en querelle.\n\nEn 1206, lors d'une grande assemblée (kurultai) de chefs mongols au bord de l'Onon, Temüjin fut proclamé Gengis Khan — « souverain universel ». Il transforma aussitôt les tribus rassemblées en une machine militaire disciplinée organisée selon des principes décimaux : unités de dix, cent, mille et dix mille. La loyauté allait à l'unité et au Khan, non au clan — un changement révolutionnaire qui mit fin aux guerres tribales ayant affaibli les Mongols durant des générations.",
      "Les armées mongoles étaient la force la plus efficace du monde médiéval, alliant mobilité, discipline, guerre psychologique et sophistication tactique. Les archers montés pouvaient couvrir 80 à 100 km par jour, opérant sur de vastes distances qui auraient immobilisé les armées d'infanterie. Avant une bataille, les émissaires mongols offraient aux villes un choix brutal : se rendre et être épargnées, ou résister et affronter la destruction totale.\n\nLes villes qui se soumettaient étaient généralement traitées avec une clémence pragmatique — leurs artisans, ingénieurs et administrateurs étaient absorbés dans la machine d'État mongole. Les villes qui résistaient étaient rasées en avertissement. Quand la grande cité de Zhongdu (l'actuelle Pékin) tomba en 1215, des voyageurs étrangers rapportèrent que les ossements de ses habitants blanchissaient les plaines sur des kilomètres. Cette combinaison de clémence et de terreur se révéla dévastatrice : la nouvelle des campagnes mongoles poussait souvent les villes à se soumettre sans combattre.",
      "À la mort de Gengis Khan en 1227, les Mongols contrôlaient un empire allant de la côte pacifique de la Chine à la mer Caspienne. Ses successeurs poussèrent encore plus loin. Ögödei Khan acheva la conquête du nord de la Chine ; Batu Khan déferla sur la Russie et la Pologne, atteignant l'Adriatique avant de se retirer. Houlagou Khan mit à sac Bagdad en 1258, tuant le calife abbasside et mettant fin à cinq siècles de suprématie culturelle islamique.\n\nÀ son apogée, l'Empire mongol était le plus grand empire terrestre contigu de l'histoire, couvrant 24 millions de kilomètres carrés — à peu près la taille de l'Afrique. Il englobait la majeure partie de la masse continentale eurasienne et tenait peut-être 100 millions de personnes sous sa domination. Aucun empire avant ou depuis n'a réalisé une expansion territoriale aussi rapide à travers des zones géographiques et climatiques aussi diverses.",
      "Paradoxalement, la conquête la plus destructrice de l'histoire créa l'une de ses périodes les plus fécondes d'échanges culturels. La Pax Mongolica (« paix mongole »), environ 1260–1350, unifia pour la première fois les routes commerciales de l'Eurasie sous un même parapluie politique. Marchands, diplomates, missionnaires et voyageurs pouvaient aller de la Chine à l'Europe avec une sécurité relative, portant biens, idées, techniques et maladies le long de la route de la Soie.\n\nLe fameux voyage de Marco Polo à la cour de Kubilaï Khan (1271–1295) ne fut possible que grâce à l'ordre mongol. La fabrication du papier, la poudre à canon et l'imprimerie chinoises voyagèrent vers l'ouest ; l'astronomie et la médecine islamiques vers l'est. Les cours mongoles recrutaient activement des gens qualifiés sans égard à la religion ou à l'origine — prêtres chrétiens, astronomes musulmans, ingénieurs chinois et bureaucrates persans servaient tous à la cour Yuan de Pékin. Cet échange cosmopolite accéléra le développement technologique et commercial qui alimenterait à terme la Renaissance européenne et les Grandes Découvertes.",
      "Les conquêtes mongoles tuèrent environ 40 millions de personnes — peut-être 10 % de la population mondiale — et altérèrent durablement le paysage démographique de l'Asie centrale et du Moyen-Orient. La population de l'Iran ne retrouva peut-être son niveau pré-mongol qu'après 700 ans. La destruction des systèmes d'irrigation de Bagdad contribua au long déclin agricole de la Mésopotamie. Les cités jadis grandes d'Asie centrale — Samarcande, Boukhara, Merv — ne retrouvèrent jamais pleinement leur vitalité d'avant les Mongols.\n\nPourtant la domination mongole créa aussi. La dynastie Yuan de Kubilaï Khan (1271–1368) apporta à la Chine un développement économique spectaculaire : le papier-monnaie fut standardisé, le Grand Canal prolongé, et le système de relais postaux (yam) permit une communication à travers l'empire d'une rapidité sans précédent. Les États successeurs mongols — l'Ilkhanat en Perse, la Horde d'or en Russie, le khanat de Djaghataï en Asie centrale — se convertirent peu à peu à l'islam et adoptèrent les cultures locales, produisant des traditions artistiques et architecturales distinctives. La longue sujétion mongole de la Russie façonna sa culture politique autocratique. Le moment mongol, si bref fût-il, réordonna durablement l'Eurasie.",
    ],
  },
  'medieval-06': {
    de: [
      "Japans Kaiserhof in Heian-kyō (dem heutigen Kyoto) erreichte im 10.–11. Jahrhundert seinen kulturellen Höhepunkt und brachte außerordentliche Literatur und Kunst hervor. Doch die Verwaltung der fernen Provinzen erforderte Krieger — berittene Bogenschützen, aus adligen Familien angeworben. Diese Provinzkrieger, Samurai („die dienen“) genannt, entwickelten sich allmählich von kaiserlichen Gefolgsleuten zu einer eigenen Militärklasse mit eigenen Werten und Ästhetik.\n\nDie Samurai-Gesellschaft war um das Herr-Vasallen-Verhältnis geordnet: Ein Samurai gelobte seinem Herrn (Daimyō) absolute Treue gegen Land und Schutz. Das entstehende Kriegerethos — später als Bushidō, „der Weg des Kriegers“, kodifiziert — betonte Treue (chū), Ehre (meiyo), Kampfkunst und die Annahme des Todes. Von einem Samurai, der seine Ehre verlor oder dessen Herr starb, wurde erwartet, rituellen Selbstmord (Seppuku) zu begehen, statt in Schande zu leben. Dieser strenge Kodex prägte die japanische Kultur über Jahrhunderte.",
      "Die Rivalität zwischen Japans zwei mächtigsten Kriegerclans — den Taira (Heike) und den Minamoto (Genji) — entlud sich im Genpei-Krieg (1180–1185), einem Konflikt, der zu einer der prägenden Erzählungen der japanischen Kultur wurde. Die Minamoto, geführt vom brillanten Feldherrn Minamoto no Yoshitsune, besiegten die Taira in einer Reihe von Schlachten, die in der Seeschlacht von Dan-no-ura gipfelten, wo der Kind-Kaiser Antoku mit der Taira-Flotte ertrank.\n\nMinamoto no Yoritomo, Yoshitsunes älterer Bruder, errichtete 1185 in Kamakura Japans erstes Shogunat (Militärregierung) — eine Parallelregierung, die den Kaiserhof faktisch verdrängte. Der Kaiser behielt die zeremonielle Autorität; die wirkliche Macht lag beim Shogun. Diese Doppelstruktur aus nomineller Kaiserherrschaft und tatsächlicher Militärregierung bestand mit Abweichungen bis 1868. Die Geschichten des Genpei-Krieges — Yoshitsunes Genie und tragisches Schicksal, der Untergang der Taira — wurden in der Erzählung von den Heike, Japans großem Kriegerepos, verewigt.",
      "Der Zen-Buddhismus, im späten 12. Jahrhundert aus China eingeführt, fand sein empfänglichstes Publikum in der Samurai-Klasse. Zens Betonung der unmittelbaren Erfahrung vor der Schrift, seine Meditationspraktiken, die geistige Klarheit unter Druck kultivierten, und seine Annahme der Vergänglichkeit fanden bei Kriegern, die dem Tod als tägliche Wirklichkeit gegenüberstanden, tiefen Widerhall. Zen-Meister wurden geistliche Berater von Shogunen wie Daimyō.\n\nDie Zen-Ästhetik prägte die japanische Kultur zutiefst. Die Teezeremonie (chanoyu), die Gartengestaltung, die Tuschmalerei (suiboku-ga), das Nō-Theater und das Blumenstecken (Ikebana) spiegeln alle die Zen-Werte von Schlichtheit, Vergänglichkeit und disziplinierter Aufmerksamkeit. Selbst die Schwertschmiedekunst wurde zur geistlichen Kunst: Ein Meisterschmied reinigte sich rituell, ehe er eine Klinge schmiedete, und das fertige Katana galt als Seele in Stahl. Diese Verschmelzung kriegerischer Zweckmäßigkeit mit verfeinertem ästhetischem Empfinden brachte eine der eigenständigsten Kulturtraditionen der Welt hervor.",
      "1274 und 1281 unternahm das Yuan-Reich Kublai Khans zwei gewaltige Invasionsversuche gegen Japan — die größten amphibischen Operationen des Mittelalters. Die erste Flotte aus 900 Schiffen und 40.000 Kriegern erreichte im November 1274 die Bucht von Hakata und schlug japanische Samurai mit überlegenen Armbrüsten, explosiven Bomben und koordinierter Infanterietaktik zurück, der einzelne japanische Krieger nicht gewachsen waren. Doch ein plötzlicher Sturm beschädigte die Flotte, und die Mongolen zogen sich zurück.\n\nDie zweite Invasion 1281 war weit größer: 4.400 Schiffe und bis zu 140.000 Mann. Nach wochenlangen Kämpfen an den Stränden und an Bord ankernder Schiffe zerstörte ein gewaltiger Taifun — der berühmte „göttliche Wind“ oder Kamikaze — den Großteil der Flotte. Japan war gerettet. Doch der Sieg hatte verheerende Folgen: Die verteidigenden Samurai erwarteten Landvergaben als Lohn, doch es gab kein erobertes Gebiet zu verteilen. Die daraus folgende wirtschaftliche Not schwächte das Kamakura-Shogunat und trug zu seinem schließlichen Zusammenbruch 1333 bei. Der Kamikaze-Mythos wurde zum Eckstein der japanischen nationalen Identität, erneut heraufbeschworen — mit tragischen Folgen — im Zweiten Weltkrieg.",
      "Der Ōnin-Krieg von 1467–1477, um die Nachfolge im Shogunat in den Straßen Kyotos ausgetragen, zerschlug, was von der Zentralgewalt geblieben war, und stürzte Japan in die Sengoku-Zeit („Streitende Reiche“) — anderthalb Jahrhunderte fast ununterbrochenen Krieges zwischen rivalisierenden Daimyō. Burgen wurden über das Land errichtet; Bauern wurden als Fußsoldaten (Ashigaru) ausgehoben; die Einführung von Feuerwaffen durch portugiesische Händler 1543 verwandelte die Taktik.\n\nDie Einigung kam durch drei aufeinanderfolgende „große Einiger“. Oda Nobunaga — rücksichtslos, erfinderisch und brillant — setzte Feuerwaffen und Stoßtaktik ein, um Rivalen zu besiegen, ehe er 1582 ermordet wurde. Sein General Toyotomi Hideyoshi, ein zur höchsten Macht aufgestiegener Bauernsohn, vollendete die Einigung und begann zwei katastrophale Invasionen Koreas. Nach Hideyoshis Tod besiegte Tokugawa Ieyasu seine Rivalen in der Schlacht von Sekigahara (1600) und errichtete das Tokugawa-Shogunat — eine stabile Regierung, die Japan die nächsten 260 Jahre in bewusster Abschottung vom Rest der Welt regieren und die Samurai-Kultur wie in Bernstein bewahren sollte, bis die Moderne Japans Türen aufzwang.",
    ],
    fr: [
      "La cour impériale du Japon à Heian-kyō (l'actuelle Kyoto) atteignit son zénith culturel aux Xe–XIe siècles, produisant une littérature et un art extraordinaires. Mais gouverner les provinces lointaines exigeait des guerriers — archers montés recrutés dans les familles aristocratiques. Ces guerriers provinciaux, appelés samouraïs (« ceux qui servent »), évoluèrent peu à peu de vassaux impériaux en une classe militaire distincte avec ses valeurs et son esthétique propres.\n\nLa société samouraï s'organisait autour de la relation seigneur-vassal : un samouraï jurait loyauté absolue à son seigneur (daimyō) en échange de terres et de protection. L'éthos guerrier qui se développa — codifié plus tard sous le nom de bushidō, « la voie du guerrier » — mettait l'accent sur la loyauté (chū), l'honneur (meiyo), l'habileté martiale et l'acceptation de la mort. Un samouraï ayant perdu son honneur ou dont le seigneur mourait était censé commettre le suicide rituel (seppuku) plutôt que vivre dans le déshonneur. Ce code austère façonna la culture japonaise durant des siècles.",
      "La rivalité entre les deux plus puissants clans guerriers du Japon — les Taira (Heike) et les Minamoto (Genji) — éclata dans la guerre de Genpei (1180–1185), conflit qui devint l'un des récits fondateurs de la culture japonaise. Les Minamoto, menés par le brillant général Minamoto no Yoshitsune, vainquirent les Taira dans une série de batailles culminant à la bataille navale de Dan-no-ura, où le jeune empereur Antoku se noya avec la flotte Taira.\n\nMinamoto no Yoritomo, frère aîné de Yoshitsune, établit le premier shogunat du Japon (gouvernement militaire) à Kamakura en 1185 — un gouvernement parallèle qui supplanta de fait la cour impériale. L'empereur conservait l'autorité cérémonielle ; le pouvoir réel appartenait au shogun. Cette structure double d'un règne impérial nominal et d'une gouvernance militaire effective persista, avec des variantes, jusqu'en 1868. Les récits de la guerre de Genpei — le génie et le sort tragique de Yoshitsune, la ruine des Taira — furent immortalisés dans le Dit des Heike, la grande épopée guerrière du Japon.",
      "Le bouddhisme zen, introduit de Chine à la fin du XIIe siècle, trouva son public le plus réceptif dans la classe samouraï. L'accent du zen sur l'expérience directe plutôt que sur l'écriture, ses pratiques de méditation cultivant la clarté d'esprit sous pression, et son acceptation de l'impermanence résonnaient profondément chez des guerriers qui affrontaient la mort au quotidien. Les maîtres zen devinrent conseillers spirituels des shoguns comme des daimyō.\n\nL'esthétique zen façonna profondément la culture japonaise. La cérémonie du thé (chanoyu), l'art des jardins, la peinture à l'encre (suiboku-ga), le théâtre nô et l'art floral (ikebana) reflètent tous les valeurs zen de simplicité, d'impermanence et d'attention disciplinée. Même la fabrication du sabre devint un art spirituel : un maître forgeron se purifiait rituellement avant de forger une lame, et le katana achevé était tenu pour une âme dans l'acier. Cette fusion de pragmatisme martial et de sensibilité esthétique raffinée produisit l'une des traditions culturelles les plus distinctives du monde.",
      "En 1274 et 1281, l'empire Yuan de Kubilaï Khan lança deux immenses tentatives d'invasion du Japon — les plus grandes opérations amphibies du Moyen Âge. La première flotte de 900 navires et 40 000 guerriers arriva dans la baie de Hakata en novembre 1274, repoussant les samouraïs japonais avec des arbalètes supérieures, des bombes explosives et des tactiques d'infanterie coordonnées que les guerriers japonais individuels n'étaient pas formés à contrer. Mais une tempête soudaine endommagea la flotte, et les Mongols se retirèrent.\n\nLa seconde invasion de 1281 fut bien plus vaste : 4 400 navires et jusqu'à 140 000 hommes. Après des semaines de combats sur les plages et à bord des navires ancrés, un typhon massif — le fameux « vent divin » ou kamikaze — détruisit l'essentiel de la flotte. Le Japon était sauvé. Mais la victoire eut des conséquences dévastatrices : les samouraïs défenseurs attendaient des dons de terres en récompense, mais il n'y avait aucun territoire conquis à distribuer. La tension économique qui s'ensuivit affaiblit le shogunat de Kamakura et contribua à son effondrement en 1333. La mythologie du kamikaze devint une pierre angulaire de l'identité nationale japonaise, invoquée de nouveau — avec des résultats tragiques — durant la Seconde Guerre mondiale.",
      "La guerre d'Ōnin de 1467–1477, livrée pour la succession shogunale dans les rues de Kyoto, brisa ce qui restait de l'autorité centrale et plongea le Japon dans la période Sengoku (« provinces en guerre ») — un siècle et demi de guerre quasi constante entre daimyō rivaux. Des châteaux s'élevèrent à travers le pays ; les paysans furent enrôlés comme fantassins (ashigaru) ; l'introduction des armes à feu par les marchands portugais en 1543 transforma la tactique.\n\nL'unification vint par trois « grands unificateurs » successifs. Oda Nobunaga — impitoyable, novateur et brillant — usa des armes à feu et de tactiques de choc pour vaincre ses rivaux avant son assassinat en 1582. Son général Toyotomi Hideyoshi, fils de paysan parvenu au pouvoir suprême, acheva l'unification et lança deux invasions catastrophiques de la Corée. Après la mort de Hideyoshi, Tokugawa Ieyasu vainquit ses rivaux à la bataille de Sekigahara (1600) et établit le shogunat Tokugawa — un gouvernement stable qui régnerait sur le Japon dans un isolement délibéré du reste du monde pendant les 260 années suivantes, préservant la culture samouraï comme dans l'ambre jusqu'à ce que l'ère moderne force l'ouverture du Japon.",
    ],
  },
  'medieval-07': {
    de: [
      "Am 8. Juni 793 überfielen seewärts gekommene Räuber das Kloster Lindisfarne vor der Küste Northumbriens, erschlugen Mönche und trugen seine Schätze fort. Der Gelehrte Alkuin, vom Hof Karls des Großen aus schreibend, war entsetzt: „Nie zuvor ist in Britannien solch ein Schrecken erschienen, wie wir ihn nun von einem heidnischen Volk erlitten haben.“ Der Überfall kündete die Wikingerzeit an — fast drei Jahrhunderte, in denen nordische Seefahrer aus Dänemark, Norwegen und Schweden die Landkarte Europas umgestalten würden.\n\nWas sie antrieb, ist noch umstritten. Bevölkerungsdruck auf begrenztem skandinavischem Ackerland, politische Verdichtung, die ehrgeizige jüngere Söhne hinausdrängte, der Reiz des unverteidigten Reichtums der Klöster und vor allem eine Revolution im Schiffbau spielten alle eine Rolle. Die Nordleute waren kein geeintes Volk oder Reich, sondern eine Streuung von Häuptlingen, Händlern und Kriegerscharen, die eine Sprache, ein Pantheon von Göttern und ein Genie für die See teilten. Ihren Opfern waren sie heidnische Ungeheuer; sich selbst waren sie Bauern, Dichter und Kaufleute, denen eine Raubsaison ein Unternehmen unter vielen war.",
      "Keine einzelne Technik prägte die Wikingerzeit mehr als das Langschiff. Klinkergebaut aus überlappenden Eichenplanken, leicht und biegsam, ging es kaum einen Meter tief, konnte aber den offenen Atlantik befahren. Ein einziges Rahsegel trieb es mit dem Wind rasch voran; Reihen von Rudern bewegten es bei Flaute oder flussaufwärts. Sein symmetrischer Rumpf konnte ohne Wenden die Richtung umkehren, und es ließ sich an jedem Ufer stranden oder über Land zwischen Wasserwegen tragen.\n\nDas bedeutete: Keine Küste, keine Flussstadt, keine Insel war sicher. Eine Wikingerflotte konnte ohne Warnung auftauchen, zuschlagen und verschwunden sein, ehe sich eine Verteidigung sammeln konnte. Dieselben Schiffe, die Paris und Sevilla in Schrecken versetzten, trugen Siedler und ihr Vieh über tausend Meilen offenen Ozeans nach Island. Das Langschiff war Kriegsschiff, Frachtboot und Ozeanentdecker in einem — und um es herum bauten die Nordleute eine maritime Kultur, unerreicht im mittelalterlichen Europa. Die großen Schiffsbestattungen von Oseberg und Gokstad in Norwegen bewahren diese Fahrzeuge fast unversehrt, ihre geschnitzten Steven noch zum Horizont gebogen.",
      "Der Raub wich Eroberung und Besiedlung. In England landete 865 ein „Großes Heidnisches Heer“ und überrannte die Königreiche Northumbrien, Ostanglien und Mercien; nur Alfreds des Großen Wessex hielt stand, und selbst Alfred musste den Norden und Osten dem dänischen Recht zugestehen — dem Danelag, dessen Ortsnamen auf „-by“ und „-thorpe“ noch heute die englische Karte prägen. Die Nordleute gründeten oder vergrößerten Städte wie Jorvik (York) und Dublin zu blühenden Zentren des Handels mit Silber, Sklaven und Handwerk.\n\nIn Franken gipfelten wiederholte Raubzüge die Seine hinauf in der Belagerung von Paris (885–886). Statt weiterzukämpfen, erkaufte der Frankenkönig Karl der Einfältige 911 den Frieden, indem er dem Wikingerführer Rollo das Land an der Seinemündung überließ — die Normandie, „das Land der Nordmänner“. Binnen weniger Generationen waren Rollos Nachfahren französischsprachige christliche Herzöge geworden; einer von ihnen, Wilhelm, sollte 1066 England erobern. Die Wikinger plünderten Europa nicht bloß — sie ließen sich darin nieder, und ihre Nachfahren wurden einige seiner mächtigsten Herrscher.",
      "Während Dänen und Norweger nach Westen blickten, wandten sich schwedische Wikinger — die Rus — nach Osten und schleppten ihre Boote zwischen den großen Flüssen der eurasischen Ebene. Der Wolga und dem Dnjepr folgend „von den Warägern zu den Griechen“, tauschten sie Pelze, Bernstein und Sklaven gegen das Silber der islamischen Kalifate; über ganz Skandinavien verstreute Horte arabischer Münzen zeichnen diese Reisen nach. Um diese Flussrouten bauten sie einen Staat, herrschten von Nowgorod und dann Kiew — die Kiewer Rus, Vorfahr Russlands und der Ukraine.\n\nDie Rus erreichten die Mauern Konstantinopels selbst, mal als Räuber, öfter als Händler und Söldner. Die byzantinischen Kaiser schätzten sie so hoch, dass sie aus nordischen und später angelsächsischen Kriegern die Elite-Warägergarde bildeten. 988 nahm der Rus-Fürst Wladimir das orthodoxe Christentum von Byzanz an und band die Ostslawen an Konstantinopel statt an Rom — eine Entscheidung, deren religiöse und kulturelle Folgen tausend Jahre später noch durch Osteuropa hallen.",
      "Die Nordleute schoben die Grenzen der bekannten Welt weiter hinaus als alle Europäer vor ihnen. Sie besiedelten Island ab etwa 874 und schufen ein bemerkenswertes Gemeinwesen, regiert vom Althing, einer der ältesten Versammlungen der Welt. Von Island aus führte Erik der Rote um 985 Siedler nach Grönland. Und von Grönland aus segelte sein Sohn Leif Eriksson noch weiter und erreichte ein Land, das er Vinland nannte — bestätigt durch die nordische Fundstätte von L'Anse aux Meadows in Neufundland, ein Beweis, dass Europäer Amerika fünf Jahrhunderte vor Kolumbus erreichten.\n\nDas Zeitalter, das in Lindisfarne begann, endete herkömmlich 1066 bei Stamford Bridge, wo der englische König Harold Godwinson das eindringende Heer Harald Hardrådas von Norwegen — des letzten großen Wikingereroberers — vernichtete. Wochen später fiel Harold selbst gegen Wilhelm von der Normandie, den Nachfahren eines Wikingers, bei Hastings. Da waren die skandinavischen Königreiche christlich und sesshaft geworden, ihre Kräfte nach innen gewandt. Doch das Wikingererbe blieb: in den Städten, die sie gründeten, den Staaten, die sie säten, den Sagas, die sie erzählten, und dem bleibenden Bild des drachenbestevten Langschiffs, das durch nördliche Meere schneidet.",
    ],
    fr: [
      "Le 8 juin 793, des pillards venus de la mer fondirent sur le monastère de Lindisfarne au large de la Northumbrie, massacrant les moines et emportant ses trésors. Le savant Alcuin, écrivant depuis la cour de Charlemagne, était atterré : « Jamais pareille terreur n'était apparue en Grande-Bretagne comme celle que nous subissons d'une race païenne. » Le raid annonçait l'âge viking — près de trois siècles où les marins nordiques du Danemark, de Norvège et de Suède allaient refaire la carte de l'Europe.\n\nCe qui les poussait fait encore débat. Pression démographique sur des terres scandinaves limitées, consolidation politique chassant d'ambitieux cadets, attrait de la richesse sans défense des monastères, et surtout une révolution dans la construction navale jouèrent tous un rôle. Les Nordiques n'étaient ni un peuple ni un empire unifié, mais une dispersion de chefs, de marchands et de bandes guerrières partageant une langue, un panthéon de dieux et un génie de la mer. Pour leurs victimes ils étaient des monstres païens ; pour eux-mêmes, des paysans, des poètes et des marchands pour qui une saison de razzia était une entreprise parmi d'autres.",
      "Aucune technique ne définit davantage l'âge viking que le langskip. Bordé à clin de planches de chêne se chevauchant, léger et souple, il tirait à peine un mètre d'eau mais pouvait affronter l'Atlantique. Une seule voile carrée le poussait vite au vent ; des rangs de rames le mouvaient dans le calme ou en remontant une rivière. Sa coque symétrique pouvait inverser sa direction sans virer, et il pouvait s'échouer sur n'importe quel rivage ou se porter par voie de terre entre les cours d'eau.\n\nCela signifiait qu'aucune côte, aucune ville fluviale, aucune île n'était sûre. Une flotte viking pouvait surgir sans prévenir, frapper et disparaître avant qu'une défense ne se rassemble. Les mêmes navires qui terrorisèrent Paris et Séville portèrent colons et bétail sur mille milles d'océan ouvert jusqu'en Islande. Le langskip était navire de guerre, cargo et explorateur océanique à la fois — et autour de lui les Nordiques bâtirent une culture maritime sans égale dans l'Europe médiévale. Les grandes sépultures navales d'Oseberg et de Gokstad en Norvège conservent ces vaisseaux presque intacts, leurs proues sculptées courbées encore vers l'horizon.",
      "La razzia céda la place à la conquête et à la colonisation. En Angleterre, une « Grande Armée païenne » débarqua en 865 et submergea les royaumes de Northumbrie, d'Est-Anglie et de Mercie ; seul le Wessex d'Alfred le Grand résista, et même Alfred dut concéder le nord et l'est au droit danois — le Danelaw, dont les toponymes en « -by » et « -thorpe » marquent encore la carte de l'Angleterre. Les Nordiques fondèrent ou firent croître des villes comme Jorvik (York) et Dublin en centres prospères de commerce d'argent, d'esclaves et d'artisanat.\n\nEn Francie, des raids répétés en remontant la Seine culminèrent dans le siège de Paris (885–886). Plutôt que de continuer à combattre, le roi franc Charles le Simple acheta la paix en 911 en octroyant au chef viking Rollon la terre à l'embouchure de la Seine — la Normandie, « le pays des hommes du Nord ». En quelques générations, les descendants de Rollon étaient devenus des ducs chrétiens francophones ; l'un d'eux, Guillaume, conquerrait l'Angleterre en 1066. Les Vikings ne se contentèrent pas de piller l'Europe — ils s'y installèrent, et leurs descendants en devinrent parmi les plus puissants souverains.",
      "Tandis que Danois et Norvégiens regardaient vers l'ouest, les Vikings suédois — les Rus — se tournèrent vers l'est, traînant leurs bateaux entre les grands fleuves de la plaine eurasienne. Suivant la Volga et le Dniepr « des Varègues aux Grecs », ils échangeaient fourrures, ambre et esclaves contre l'argent des califats islamiques ; des trésors de monnaies arabes trouvés à travers la Scandinavie retracent ces voyages. Autour de ces routes fluviales ils bâtirent un État, régnant depuis Novgorod puis Kiev — la Rus de Kiev, ancêtre de la Russie et de l'Ukraine.\n\nLes Rus atteignirent les murs de Constantinople elle-même, parfois en pillards, plus souvent en marchands et mercenaires. Les empereurs byzantins les prisaient tant qu'ils formèrent la garde varègue d'élite de guerriers nordiques puis anglo-saxons. En 988, le prince rus Vladimir accepta le christianisme orthodoxe de Byzance, liant les Slaves orientaux à Constantinople plutôt qu'à Rome — décision dont les conséquences religieuses et culturelles résonnent encore à travers l'Europe de l'Est mille ans plus tard.",
      "Les Nordiques repoussèrent les limites du monde connu plus loin qu'aucun Européen avant eux. Ils colonisèrent l'Islande à partir de 874 environ, créant un remarquable État régi par l'Althing, l'une des plus anciennes assemblées du monde. Depuis l'Islande, Erik le Rouge conduisit des colons au Groenland vers 985. Et depuis le Groenland, son fils Leif Erikson navigua plus loin encore, atteignant une terre qu'il appela Vinland — confirmée par le site nordique de L'Anse aux Meadows à Terre-Neuve, preuve que les Européens atteignirent les Amériques cinq siècles avant Colomb.\n\nL'âge commencé à Lindisfarne s'acheva, par convention, à Stamford Bridge en 1066, où le roi anglais Harold Godwinson détruisit l'armée d'invasion de Harald Hardrada de Norvège — le dernier grand conquérant viking. Des semaines plus tard, Harold lui-même tomba devant Guillaume de Normandie, descendant d'un Viking, à Hastings. À cette date, les royaumes scandinaves étaient devenus chrétiens et sédentaires, leurs énergies tournées vers l'intérieur. Mais l'héritage viking perdura : dans les villes qu'ils fondèrent, les États qu'ils semèrent, les sagas qu'ils contèrent, et l'image durable du langskip à proue de dragon fendant les mers du Nord.",
    ],
  },
  'medieval-08': {
    de: [
      "711 setzte ein berberisch-arabisches Heer unter Tariq ibn Ziyad von Nordafrika über die Meerenge und zerstörte in der Schlacht von Guadalete das westgotische Königreich Hispania. Der Fels, an dem er landete, trägt noch seinen Namen: Dschabal Tariq — „Tariqs Berg“ — Gibraltar. Binnen eines Jahrzehnts erstreckte sich die muslimische Herrschaft über den Großteil der Halbinsel, die arabische Sprecher al-Andalus nannten.\n\nDer Vorstoß nach Franken wurde 732 von Karl Martell bei Tours gestoppt, und die Pyrenäen wurden eine grobe Grenze. In den Bergen Asturiens im Norden gewann ein westgotischer Edelmann namens Pelayo bei Covadonga (um 722) ein Gefecht, das spätere Chronisten als ersten Funken der Reconquista erinnern würden.",
      "Als die Abbasiden 750 die Umayyaden-Dynastie in Damaskus massakrierten, entkam ein Prinz nach Westen. Abd ar-Rahman I. erreichte Iberien und baute in Córdoba ein unabhängiges Emirat; sein Nachfahre Abd ar-Rahman III. rief sich 929 zum Kalifen aus. Das Córdoba des 10. Jahrhunderts war nach europäischen Maßstäben überwältigend: Hunderttausende Einwohner, gepflasterte und lampenerleuchtete Straßen, Hunderte Bäder und Bibliotheken und der Wald gestreifter Hufeisenbögen der Großen Moschee.\n\nEine deutsche Nonnen-Chronistin nannte die Stadt „die Zierde der Welt“. Juden, Christen und Muslime lebten in einem funktionierenden — wenn auch ungleichen — Zusammenleben, später convivencia genannt. Die kalifale Bibliothek al-Hakams II. soll 400.000 Bände gehalten haben, als die größten lateinischen Bibliotheken einige hundert zählten.",
      "Nachdem der Kalifat 1031 in zerstrittene Taifa-Kleinstaaten zerfallen war, drängten die christlichen Königreiche des Nordens — León, Kastilien, Aragón, Portugal, Navarra — nach Süden. Toledo fiel 1085; die Taifa-Könige riefen die Almoraviden, dann die Almohaden, aus Marokko herbei, und die Halbinsel schwankte zwei Jahrhunderte hin und her. Der entscheidende Schlag kam 1212 bei Las Navas de Tolosa, als ein vereintes christliches Heer die Almohaden-Macht brach.\n\nCórdoba fiel 1236 und Sevilla 1248 und ließen nur das Bergemirat Granada — Heimat des erlesenen Alhambra-Palasts — als tributpflichtigen muslimischen Staat für weitere 250 Jahre. Die Grenzwelt aus Raub, Lösegeld und wechselnden Loyalitäten brachte Gestalten wie El Cid hervor, der für christliche wie muslimische Geldgeber kämpfte und zum Nationalepos Kastiliens wurde.",
      "Ferdinand von Aragón und Isabella von Kastilien, die „Katholischen Könige“, deren Ehe Spanien einte, nahmen Granada am 2. Januar 1492 nach einem zehnjährigen Krieg. Im selben Jahr vertrieben sie Spaniens Juden und finanzierten Kolumbus — drei Ereignisse, die den Wendepunkt von der mittelalterlichen zur frühneuzeitlichen Geschichte markieren. Muslime wurden binnen einer Generation zwangsbekehrt, und die Inquisition überwachte die Bekehrten.\n\nAl-Andalus hinterließ Europa ein tiefes Erbe. Durch die Übersetzerwerkstätten Toledos empfing die lateinische Christenheit Aristoteles mit den Kommentaren des Averroes, al-Chwarizmis Algebra und die arabischen Ziffern. Das Spanische trägt Tausende arabischer Wörter — von alcalde (Bürgermeister) bis azúcar (Zucker) —, und die Paläste von Sevilla und die Alhambra sprechen noch die Bildsprache des verschwundenen Kalifats.",
      "Das Córdoba des zwölften Jahrhunderts brachte binnen einer Generation zwei der einflussreichsten Denker des gesamten Mittelalters hervor. Ibn Rushd — Averroes für die lateinische Welt — schrieb Kommentare zu Aristoteles von solcher Durchdringung, dass das christliche Europa ihn schlicht „den Kommentator“ nannte; sein Beharren, dass Vernunft und Offenbarung nicht wirklich in Widerspruch geraten könnten, erschütterte drei Religionen. Sein fast Zeitgenosse Moses Maimonides, der größte jüdische Philosoph der Zeit, floh als Junge vor der Almohaden-Verfolgung und schrieb seinen Führer der Unschlüssigen auf Arabisch in Ägypten. Dass beide Männer — einer Muslim, einer Jude, beide denselben griechischen Philosophen in der Tradition derselben Stadt lesend — ihre Wirkung gleichermaßen in Pariser Hörsälen wie in hebräischen Akademien entfalteten, ist al-Andalus im Kleinen: eine Zivilisation, deren Argumente ihre Grenzen überlebten.",
    ],
    fr: [
      "En 711, une armée arabo-berbère sous Tariq ibn Ziyad franchit le détroit depuis l'Afrique du Nord et détruisit le royaume wisigoth d'Hispanie à la bataille du Guadalete. Le rocher où il débarqua porte encore son nom : Jabal Tariq — « la montagne de Tariq » — Gibraltar. En une décennie, la domination musulmane s'étendait sur l'essentiel de la péninsule, que les arabophones appelaient al-Andalus.\n\nL'avancée en Francie fut stoppée par Charles Martel à Tours en 732, et les Pyrénées devinrent une frontière approximative. Dans les montagnes des Asturies au nord, un noble wisigoth nommé Pélage remporta une escarmouche à Covadonga (v. 722) que les chroniqueurs ultérieurs retiendraient comme la première étincelle de la Reconquista.",
      "Quand les Abbassides massacrèrent la dynastie omeyyade à Damas en 750, un prince s'échappa vers l'ouest. Abd al-Rahman Ier atteignit l'Ibérie et bâtit un émirat indépendant à Cordoue ; son descendant Abd al-Rahman III se proclama calife en 929. La Cordoue du Xe siècle était stupéfiante selon les critères européens : des centaines de milliers d'habitants, des rues pavées et éclairées, des centaines de bains et de bibliothèques, et la forêt d'arcs outrepassés bicolores de la Grande Mosquée.\n\nUne chroniqueuse nonne allemande appela la ville « l'ornement du monde ». Juifs, chrétiens et musulmans vivaient sous une coexistence fonctionnelle — quoique inégale — appelée plus tard convivencia. La bibliothèque califale d'al-Hakam II aurait renfermé 400 000 volumes quand les plus grandes bibliothèques latines en comptaient quelques centaines.",
      "Après l'éclatement du califat en petits États taifas querelleurs en 1031, les royaumes chrétiens du nord — León, Castille, Aragon, Portugal, Navarre — poussèrent vers le sud. Tolède tomba en 1085 ; les rois taifas appelèrent les Almoravides, puis les Almohades, du Maroc, et la péninsule oscilla deux siècles durant. Le coup décisif vint à Las Navas de Tolosa en 1212, quand une armée chrétienne unie brisa la puissance almohade.\n\nCordoue tomba en 1236 et Séville en 1248, ne laissant que l'émirat de montagne de Grenade — siège du raffiné palais de l'Alhambra — comme État musulman tributaire pour 250 ans encore. Le monde frontalier de razzia, de rançon et d'allégeances changeantes produisit des figures comme le Cid, qui combattit pour des maîtres chrétiens comme musulmans et devint l'épopée nationale de la Castille.",
      "Ferdinand d'Aragon et Isabelle de Castille, les « Rois catholiques » dont le mariage unit l'Espagne, prirent Grenade le 2 janvier 1492 après une guerre de dix ans. La même année, ils expulsèrent les Juifs d'Espagne et financèrent Colomb — trois événements marquant le pivot de l'histoire médiévale à moderne. Les musulmans furent convertis de force en une génération, et l'Inquisition surveilla les convertis.\n\nAl-Andalus laissa à l'Europe un profond héritage. Par les ateliers de traduction de Tolède, la chrétienté latine reçut Aristote avec les commentaires d'Averroès, l'algèbre d'al-Khwarizmi et les chiffres arabes. L'espagnol porte des milliers de mots arabes — de alcalde (maire) à azúcar (sucre) — et les palais de Séville et l'Alhambra parlent encore le langage visuel du califat disparu.",
      "La Cordoue du XIIe siècle produisit, en une génération, deux des penseurs les plus influents de tout le Moyen Âge. Ibn Rushd — Averroès pour le monde latin — écrivit des commentaires sur Aristote si pénétrants que l'Europe chrétienne l'appela simplement « le Commentateur » ; son insistance sur le fait que raison et révélation ne pouvaient vraiment s'opposer ébranla trois religions. Son quasi-contemporain Moïse Maïmonide, le plus grand philosophe juif de l'époque, fuit enfant la persécution almohade et écrivit son Guide des égarés en arabe en Égypte. Que les deux hommes — l'un musulman, l'autre juif, lisant tous deux le même philosophe grec dans la tradition de la même ville — aient exercé leur influence aussi bien dans les amphithéâtres de Paris que dans les académies hébraïques, c'est al-Andalus en miniature : une civilisation dont les arguments survécurent à ses frontières.",
    ],
  },
  'medieval-09': {
    de: [
      "Der Krieg begann als dynastischer Streit: Als die französische Königslinie 1328 ausstarb, beanspruchte Eduard III. von England — durch seine Mutter Enkel eines französischen Königs — die Krone Frankreichs gegen den neuen Valois-König. Unter dem Rechtsstreit lagen ältere Reibungen: das englisch gehaltene Gascogne, der Wollhandel mit Flandern und die französische Unterstützung Schottlands.\n\nNiemand beabsichtigte ein Jahrhundert Krieg. Doch der Konflikt schleppte sich in Phasen dahin — spektakuläre englische Siege, erschöpfte Waffenstillstände, französische Erholung — und verwandelte dabei beide Königreiche. Untertanen, die sich für Normannen oder Gascogner, Burgunder oder Picarden gehalten hatten, lernten langsam, sich als Engländer oder Franzosen zu begreifen.",
      "Bei Crécy (1346) und Poitiers (1356) vernichteten englische Heere, ein Bruchteil der Größe ihrer Gegner, die Blüte des französischen Rittertums. Das Werkzeug war der Langbogen: ein zwei Meter langer Eibenstab, dessen Schützen ein Dutzend Pfeile pro Minute abschießen konnten, den Himmel verdunkelten und die Pferde angreifender Ritter in Raserei trieben. Bei Poitiers wurde der französische König selbst gefangen und für eine Summe losgekauft, die dem doppelten Jahreseinkommen seines Reiches entsprach.\n\nHeinrich V. nahm den Krieg wieder auf und wiederholte bei Azincourt (1415), im Schlamm, der gepanzerte Männer verschlang, das Gemetzel. Die Lehre war sozial wie militärisch: Ein Bauer mit einem Bogen konnte einen Herrn in Plattenpanzer töten. Das Zeitalter, in dem die aristokratische Reiterei das Schlachtfeld beherrschte, ging zu Ende.",
      "Bis 1428 schien Frankreich am Ende — sein Norden besetzt, sein König ungekrönt, Orléans belagert. Dann stellte sich ein siebzehnjähriges Bauernmädchen aus Domrémy bei Hofe vor und behauptete, Stimmen von Heiligen hätten ihr befohlen, Frankreich zu retten. Mit Rüstung und Heer versehen, entsetzte Jeanne d'Arc Orléans in neun Tagen und führte den Dauphin durch feindliches Gebiet, um in Reims als Karl VII. gekrönt zu werden — das heilige Ritual, das ihn unzweideutig zum König machte.\n\n1430 von burgundischen Verbündeten Englands gefangen, wurde Jeanne verkauft, von einem Kirchengericht in Rouen verurteilt und mit neunzehn auf dem Scheiterhaufen verbrannt. Ein Wiederaufnahmeverfahren von 1456 hob das Urteil auf; 1920 wurde sie heiliggesprochen. Sie bleibt vielleicht die außerordentlichste Gestalt des gesamten Mittelalters: eine des Lesens unkundige Jugendliche, die die Geschichte zweier Königreiche umlenkte.",
      "Frankreichs endgültige Erholung war ebenso verwaltungstechnisch wie heroisch. Karl VII. schuf Europas erstes stehendes königliches Heer und besteuerte das Reich, um es zu bezahlen — und für die neue Pulverartillerie der Brüder Bureau, deren Belagerungszüge englisch gehaltene Städte in der Normandie und Gascogne wie Nüsse knackten. Bei Castillon (1453), der letzten Schlacht des Krieges, vernichteten französische Kanonen einen englischen Angriff.\n\nEngland behielt nur Calais und wandte sich nach innen — in die Rosenkriege, geführt von Herren mit Privatheeren, die der französische Krieg ausgebildet hatte. Frankreich ging mit dauerhafter Besteuerung, einem stehenden Heer und einer Monarchie hervor, stark genug, Europa zu beherrschen. Der Krieg hatte über feudale Lehnstreue begonnen; er endete, nachdem er einen Großteil des modernen Staates erfunden hatte.",
      "Nach Crécy belagerte Eduard III. elf Monate den Hafen Calais und hungerte ihn 1347 zur Übergabe aus. Der König verlangte, dass sechs der führenden Bürger der Stadt barfuß, mit Stricken um den Hals und den Stadtschlüsseln in den Händen herauskämen — er gedachte, sie zu hängen. Der reichste Bürger, Eustache de Saint-Pierre, meldete sich zuerst; fünf weitere folgten. Nach dem Chronisten Froissart wurden sie im letzten Augenblick verschont, als Königin Philippa, hochschwanger, vor ihrem Gatten niederkniete und um ihr Leben bat. Calais blieb über zwei Jahrhunderte Englands Stützpunkt in Frankreich — und die sechs Bürger, in Rodins berühmter Skulptur verewigt, wurden zum dauerhaftesten Bild bürgerlichen Muts des Krieges: gewöhnliche Stadtleute, die dem Tod entgegengingen, damit ihre Nachbarn essen konnten.",
    ],
    fr: [
      "La guerre commença comme une querelle dynastique : à l'extinction de la lignée royale française en 1328, Édouard III d'Angleterre — petit-fils d'un roi de France par sa mère — revendiqua la couronne de France contre le nouveau roi Valois. Sous la querelle juridique couvaient de vieilles frictions : la Gascogne tenue par les Anglais, le commerce de la laine avec la Flandre et le soutien français à l'Écosse.\n\nNul ne voulut un siècle de guerre. Mais le conflit s'éternisa par phases — victoires anglaises spectaculaires, trêves épuisées, redressement français — transformant au passage les deux royaumes. Des sujets qui s'étaient crus normands ou gascons, bourguignons ou picards, apprirent peu à peu à se penser anglais ou français.",
      "À Crécy (1346) et à Poitiers (1356), des armées anglaises d'une fraction de la taille de leurs adversaires anéantirent la fleur de la chevalerie française. L'instrument était l'arc long : un fût d'if de deux mètres dont les archers pouvaient lâcher une douzaine de flèches par minute, obscurcissant le ciel et affolant les chevaux des chevaliers chargeants. À Poitiers, le roi de France lui-même fut capturé et libéré contre une rançon égale à deux fois le revenu annuel de son royaume.\n\nHenri V reprit la guerre et, à Azincourt (1415), dans une boue qui engloutissait les hommes cuirassés, répéta le massacre. La leçon était sociale autant que militaire : un paysan armé d'un arc pouvait tuer un seigneur en armure de plates. L'âge où la cavalerie aristocratique régnait sur le champ de bataille touchait à sa fin.",
      "En 1428, la France semblait finie — son nord occupé, son roi non sacré, Orléans assiégée. Puis une paysanne de dix-sept ans de Domrémy se présenta à la cour, affirmant que des voix de saints lui avaient ordonné de sauver la France. Dotée d'une armure et d'une armée, Jeanne d'Arc leva le siège d'Orléans en neuf jours et mena le dauphin à travers le territoire ennemi pour être sacré Charles VII à Reims — le rituel sacré qui le faisait roi sans ambiguïté.\n\nCapturée par les alliés bourguignons de l'Angleterre en 1430, Jeanne fut vendue, jugée par un tribunal ecclésiastique à Rouen et brûlée vive à dix-neuf ans. Un procès en révision de 1456 annula le verdict ; en 1920 elle fut canonisée. Elle reste peut-être la figure la plus extraordinaire de tout le Moyen Âge : une adolescente illettrée qui réorienta l'histoire de deux royaumes.",
      "Le redressement final de la France fut autant administratif qu'héroïque. Charles VII créa la première armée royale permanente d'Europe et taxa le royaume pour la financer — ainsi que la nouvelle artillerie à poudre des frères Bureau, dont les trains de siège fendaient les villes tenues par les Anglais en Normandie et en Gascogne comme des noix. À Castillon (1453), dernière bataille de la guerre, les canons français anéantirent une charge anglaise.\n\nL'Angleterre ne garda que Calais et se tourna vers l'intérieur — vers la guerre des Deux-Roses, menée par des seigneurs aux armées privées que la guerre de France avait formées. La France émergea avec une fiscalité permanente, une armée permanente et une monarchie assez forte pour dominer l'Europe. La guerre avait commencé pour un hommage féodal ; elle s'acheva ayant inventé une grande part de l'État moderne.",
      "Après Crécy, Édouard III assiégea le port de Calais onze mois, l'affamant jusqu'à la reddition en 1347. Le roi exigea que six des principaux citoyens de la ville sortent pieds nus, la corde au cou et les clés de la ville en main — comptant les pendre. Le plus riche bourgeois, Eustache de Saint-Pierre, se porta volontaire le premier ; cinq autres suivirent. Selon le chroniqueur Froissart, ils furent épargnés au dernier moment quand la reine Philippa, enceinte jusqu'aux yeux, s'agenouilla devant son époux et implora leur grâce. Calais resta plus de deux siècles le point d'appui de l'Angleterre en France — et les six bourgeois, immortalisés dans la célèbre sculpture de Rodin, devinrent l'image la plus durable du courage civique de la guerre : d'ordinaires citadins marchant vers la mort pour que leurs voisins puissent manger.",
    ],
  },
};
